programs.sol:
"""Respond most strongly to single-letter pieces X, Y and Z.

Training examples suggest a character/word-boundary response, not just a
math-topic response: these pieces occur in names and identifiers too.
Capitals give a large negative value; lowercase letters give a smaller
one. Continuing a word, especially an uppercase word, weakens the response.
Dots, slashes, hyphens and underscores strengthen lowercase responses.
Recent Spanish/Slavic word and diacritic cues weaken space-prefixed y/z.
Short uppercase XYZ strings and two-letter title-case pieces beginning
with X/Y/Z get a modest negative value. All other pieces get zero.
State resets on a change of document.
"""

READS = ()
SPANISH = frozenset(
    'de la el que en los del las por para una un con se su es al lo'.split()
)
SLAVIC = frozenset('się nie jest na jak za ze dla'.split())
SLAVIC_MARKS = frozenset('ąćęłńśźżřěšžčůďťňľĺŕ')
LOWER = {'x': -0.23, 'y': -0.61, 'z': -0.66}
WITHIN_WORD = {'x': -0.13, 'y': 0.04, 'z': -0.14}
BARE = {'x': -0.13, 'y': -0.55, 'z': -0.66}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0.0, 0.0)
    _, last, capitals, spanish, slavic = carry
    token = prefix.token_strings[-1]
    letters = ''.join(c for c in token if c.isalpha())
    # At a singleton letter, everything before it is its attached prefix.
    lead = token[:token.find(letters)]
    value = 0.0
    if len(letters) == 1 and letters in 'XYZxyz':
        c = letters
        if c.isupper():
            value = -1.66 if c == 'Z' else -2.0
            if not lead:
                if capitals:
                    if c == 'Y':
                        value = -0.85 if capitals == 1 else -0.25
                        if capitals >= 4:
                            value = 0.0
                    else:
                        value = -0.95 if c == 'X' else -0.82
                        if capitals >= 3:
                            value += 0.30
                elif last.isdigit():
                    value *= 0.82
                elif c != 'Z':
                    value -= 0.10
            elif lead[-1] in '([,':
                value *= 0.78
        else:
            value = LOWER[c]
            if not lead:
                value = WITHIN_WORD[c] if last.isalpha() else BARE[c]
                if c == 'x' and capitals:
                    value = 0.06
                elif last.isdigit():
                    value *= 0.77
            elif lead.isspace():
                if (c == 'y' and spanish > 1.5) or (c == 'z' and slavic > 1.5):
                    value = -0.23
            elif lead[-1] == '.':  # member/property notation
                value -= 0.69
            elif lead[-1] in '/-':  # paths and hyphenated identifiers
                value -= 0.45
            elif lead[-1] == '_':  # identifier suffix
                value -= 0.24
            elif c == 'x' and lead[-1] in '(\\':
                value = -0.09
    elif 2 <= len(letters) <= 4 and all(c in 'XYZ' for c in letters):
        value = -0.85
    elif len(letters) == 2 and letters[0] in 'XYZ' and letters[1].islower():
        value = -0.40

    word = token.strip().lower()
    spanish = spanish * 0.97 + float(word in SPANISH)
    slavic = slavic * 0.97 + float(word in SLAVIC)
    slavic += 0.5 * sum(c in SLAVIC_MARKS for c in token)
    for char in token:
        capitals = capitals + 1 if char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' else 0
    return (doc, token[-1:] or last, capitals, spanish, slavic), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:4097 responds (negatively) to the letters X, Y and Z.

The activation is almost entirely a function of the token: the same letter token gives
nearly the same value wherever it appears. Typical values on training text:

- capital letters as a standalone token ("X", " Y", "Z") or after punctuation ("(X", "-Y"):
  strongly negative: X about -1.9, Y about -1.8, Z about -1.5 (the largest responses reach -3);
- the Cyrillic look-alike Х: about -0.7;
- lowercase y and z: moderately negative, about -0.4;
- lowercase x: weakly negative, about -0.15;
- every other token, including the other letters of the alphabet: about 0.

So this is a detector for the unknown and coordinate letters of algebra (x, y, z and X, Y,
Z), with the capitals about four times stronger than the lowercase y and z.
"""

READS = ()

CAPITAL_VALUE = {"X": -1.9, "Y": -1.8, "Z": -1.5, "Х": -0.7}
LOWER_VALUE = {"y": -0.4, "z": -0.4, "x": -0.15}


def _letters(token):
    # the token with any leading space or punctuation removed, e.g. " (X" -> "X"
    i = 0
    while i < len(token) and not token[i].isalpha():
        i += 1
    return token[i:]


def step(carry, prefix, upstream):
    core = _letters(prefix.token_strings[-1])
    value = CAPITAL_VALUE.get(core, LOWER_VALUE.get(core, 0.0))
    return carry, value

programs.luna:
"""Give a negative score to the familiar math/science labels X, Y and Z.

These capital variable names are the clearest response of the component; lowercase
x, y and z get a smaller score, especially when they appear as separate tokens.
"""
READS = ()

PUNCTUATION = " \t\r\n.,:;()[]{}+-=*/_\\'\"|<>!?`~"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    core = token.strip(PUNCTUATION)
    if len(core) != 1:
        return None, 0.0

    letter = core
    leading_space = token[:1].isspace()
    if letter in "XYZ":
        values = {"X": -2.0, "Y": -2.05, "Z": -1.55}
        value = values[letter] if leading_space else values[letter] * 0.72
        if token != letter and not leading_space:
            value *= 0.75
        return None, value

    if letter in "xyz":
        values = {"x": -0.22, "y": -0.52, "z": -0.48}
        value = values[letter]
        if leading_space:
            return None, value
        if token != letter:
            value *= 1.35
        return None, value

    return None, 0.0

programs.sol:
"""A negative lexical END/endpoint signal, not a sentence-ending detector.

Harvested peaks concentrate on 'end' spellings and terminal vocabulary.
The estimates distinguish word onsets, fragments, inflections, and code syntax;
physical-end modifiers strengthen the response.  'End of' retains a response
on 'of'.  A small set of Chinese endpoint/ending terms is also recognized.
Everything else predicts zero, leaving smaller, less systematic effects out.
"""

READS = ()

# Whole-word and word-fragment strengths, respectively.
END_FORMS = {'end': (-3.0, -1.25), 'ends': (-2.85, -0.95),
             'ended': (-1.74, -0.4), 'ending': (-1.53, -0.4),
             'endings': (-1.47, -0.4)}
SPATIAL = frozenset('''front back rear upper lower top bottom left right
leading trailing proximal distal free open closed tight high far other
one either each opposite both'''.split())
# Stems making words like append, depend, extend, friend, and pretend.
INTERNAL_STEMS = frozenset('''app att am bl b cont def dep desc ext exp fri
l m p pret recomm r s sp susp t tr v'''.split())
CHINESE_END = {
    '端': -7.0, '两端': -6.3, '前端': -4.9, '末端': -3.8,
    '终端': -3.2, '高端': -3.1, '客户端': -2.5, '云端': -2.2,
    '末': -1.47, '结束': -1.06, '周末': -0.96, '年末': -0.8,
    '終': -0.6, '终': -0.7, '尽': -0.4,
}


def response(token, previous):
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    stem = previous.strip().lower()
    if word in CHINESE_END:
        return CHINESE_END[word]
    if lower in END_FORMS:
        value = END_FORMS[lower][0 if spaced else 1]
        if spaced:
            if word == 'End':
                value = -2.55
            elif word == 'END':
                value = -2.0
            if lower == 'end':
                if stem in SPATIAL:
                    value -= 0.65
                elif not any(c.isalpha() for c in previous):
                    value += 0.65
        elif token.startswith('\t'):
            value = -1.65
        elif word == 'End':
            value = -2.15
        elif lower == 'end' and '\\' in previous:
            value = -0.7
        elif stem in {'front', 'back'}:
            value = -3.0 if stem == 'front' else -2.4
        elif stem in INTERNAL_STEMS:
            value = -0.25
        elif not previous or not previous[-1].isalnum():
            value = -1.9 if lower == 'end' else -1.0
        return value
    if lower[1:] == 'end' and not lower[:1].isalnum():
        return -4.0 if lower == '-end' else -1.7
    if lower in {'-ended', '-ending'}:
        return -2.4 if lower == '-ended' else -1.25
    technical = lower.lstrip('_./(')
    if technical in {'frontend', 'backend'}:
        if spaced and word[:1].islower():
            return -3.05 if technical == 'frontend' else -2.26
        return -1.9 if technical == 'frontend' else -1.6
    if technical.startswith('endpoint'):
        return -1.55
    if lower in {'ende', 'endo', 'ender', 'enders', 'endi', 'enden', 'endoth'}:
        return -1.1 if spaced and lower == 'ende' else (
            -0.3 if lower == 'enden' else -0.6)
    if lower.lstrip('-_') in {'terminal', 'terminals'}:
        return -3.0 if token.startswith('-') else (-2.2 if spaced else -1.6)
    if lower == 'termin':
        return -1.5 if spaced else -0.7
    if lower in {'terminate', 'terminated', 'terminates', 'terminating', 'termination'}:
        return -0.8
    if lower in {'weekend', 'weekends'}:
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    # Byte fragments can complete a Chinese character only when decoded together.
    if '\ufffd' in token and previous:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in CHINESE_END:
            token = completed
    value = response(token, previous)
    if token.strip().lower() in {'of', '-of'}:
        if previous.strip().lower() in {'end', 'frontend'}:
            value = -1.14 if previous.startswith(' ') else -0.7
        elif previous.strip().lower() == 'ends':
            value = -0.68
    return (doc, token), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:4099 (draft 2): an "END" word detector.

This component writes a strongly NEGATIVE signal into the residual stream whenever
the current token is the word "end" or a close relative of it: " end", " ends",
"-end" (back-end, high-end), "terminal", "frontend", "backend", and the Chinese
character 端 ("end / extremity"). It is weaker on "ended", "ending", "END",
"endpoint", and on "terminate / termination", and it is 0 on words that only
contain "end" by accident ("friend", "send", "spend", "render", "append",
"weekend", "calendar", "<|endoftext|>"). It also carries a little of the
"end" meaning onto the word " of" in "the end of ...".

Predicted activation: a few fixed values by tier, 0 elsewhere.
"""

import re

READS = ()

STRONG = {"end", "ends", "terminal", "terminals", "frontend", "backend"}
MID = {"ended", "ending", "endpoint", "endpoints", "endings", "end", "ends", "terminal", "backend"}
WEAK = {"terminate", "termination", "terminated", "termin"}
ZH = {"端": -7.0, "高端": -3.0, "末": -1.4, "结束": -1.1, "终": -0.6, "终点": -1.1}
END_LIKE = {"end", "ends", "ended", "ending", "endings", "endpoint", "endpoints"}


def letters(token):
    return re.sub(r"[^a-z]", "", token.lower())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if token in ZH:
        value = ZH[token]
    elif token == "-end" or token == "-terminal":
        value = -4.5
    elif token == " of" and letters(previous) in END_LIKE:
        value = -1.0
    else:
        word = letters(token)
        if word in STRONG and (token[:1] in " -_.(/=\t#" or token == "/backend"):
            value = -3.0
        elif word in MID:
            value = -1.5
        elif word in WEAK:
            value = -0.7
    return carry, float(value)

programs.sol:
"""A partial lexical approximation of a weak first-layer component.

Use fitted means for explicit word classes and four chat delimiters. Listed
reflexives and scope words tend positive; listed comparative markers,
intensifiers, and human/history references tend negative. This is not a single
semantic detector: most activation variation remains unexplained. Read only
the current token, with no contextual state; use a small negative fallback.
"""

READS = ()

# Each named class has one fitted mean, shared by its listed spellings.
WORD_CLASSES = {
    'reflexive pronouns': (0.05473,
        'herself himself itself myself ourselves themselves yourself '
        'yourselves '
    ),
    'ownership, extent, alternatives': (0.0815,
        'either else entire own whole '
    ),
    'possibility and equality': (0.05901,
        'common equal possible '
    ),
    'intensifiers': (-0.04948,
        'almost especially quite really too very '
    ),
    'necessity and significance': (-0.0628,
        'necessary significant '
    ),
    'comparison and linking': (-0.06213,
        'addition compared comparison contrast despite due resulting '
        'similar such whether '
    ),
    'unspecified people': (-0.04793,
        'everyone human individual individuals man men people person '
        'someone '
    ),
    'selected social/history terms': (-0.06214,
        'age historical history life local modern national role social '
        'united young '
    ),
    'past and initial time': (-0.06807,
        'initial past previous season times today yesterday '
    ),
    'following time': (0.02354,
        'later next once soon then '
    ),
    'mentioning': (-0.08263,
        'mention mentioned mentions named '
    ),
    'knowledge and result vocabulary': (-0.05721,
        'believe believes found knowing known results unknown '
    ),
    'calculation': (-0.0616,
        'calculate calculated coordinates procedure variables '
    ),
    'properties and parts': (0.04855,
        'collection component components dimension length parts '
        'properties property scale '
    ),
    'motion': (0.03807,
        'across follow following into move moved moves moving send sent '
        'take taken towards '
    ),
    'reflexive stem': (-0.0411,
        'self '
    ),
    'Romance purpose/instrumental prepositions': (0.05148,
        'com con para per por pour '
    ),
    'russian prepositions': (0.02802,
        'без для до за из к на от по под при с '
    ),
    'latin prefixes': (0.04189,
        'inter pre '
    ),
    'universal frequency': (0.06609,
        'ever never '
    ),
    'universal quantity': (0.02105,
        'each every '
    ),
    'indefinite quantity': (-0.01355,
        'all any both some '
    ),
    'past auxiliary': (-0.02127,
        'had was '
    ),
    'selected auxiliary forms': (-0.02221,
        'am do does done have may '
    ),
    'plural copula': (0.01213,
        'are were '
    ),
    'permission verb': (0.03258,
        'Let let '
    ),
}
CLASSES = tuple((mean, frozenset(words.split()))
                for mean, words in WORD_CLASSES.values())

TAGS = {
    '<think>': 0.12578,
    '</think>': -0.09817,
    '<tool_response>': 0.09061,
    '<|im_end|>': 0.01917,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in TAGS:
        return None, TAGS[token]
    # Leading space separates word-start tokens from internal word fragments.
    if token.startswith(' ') and token[1:] == token[1:].strip():
        word = token[1:].lower()
        for mean, words in CLASSES:
            if word in words:
                return None, mean
    return None, -0.00382

"""Predict a negative response to letter-like endings in L.

Bare L/l and consonant-L fragments are strongest. Leading spaces,
longer spellings, and vowels weaken the response. A bare L also notices
an adjacent letter in the previous token. The coefficients distinguish
preceding letters, not vocabulary IDs. Smaller responses cover L-like
letters in other scripts; unrelated endings get zero.
"""
import unicodedata

READS = ()
CONSONANT_L = {
    'b': 1.68, 'c': 1.52, 'd': 3.02, 'f': 2.03, 'g': 2.54,
    'h': 2.24, 'j': 2.0, 'k': 2.78, 'm': 3.04, 'n': 2.29,
    'p': 1.32, 'q': 3.1, 'r': 3.65, 's': 3.35, 't': 3.1,
    'v': 1.8, 'w': 2.14, 'x': 1.81, 'y': 1.48, 'z': 2.23,
}
VOWEL_L = {'a': 0.0, 'e': 0.0, 'i': 0.17, 'o': 0.25, 'u': 0.57}
# Familiar computing abbreviations behave more like words than raw letters.
COMPUTING = {
    'url': 0.85, 'html': 0.0, 'xml': 1.05, 'yaml': 1.4,
    'yml': 1.2, 'sql': 0.95, 'ctrl': 0.15,
}


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    s = raw.strip()
    word = s.lstrip('._-/()[]{},:;=+\\')
    low, spaced = word.lower(), raw[:1].isspace()
    plain = ''.join(c for c in unicodedata.normalize('NFD', low)
                    if not unicodedata.combining(c))
    n, strength = len(plain), 0.0
    if plain == 'l':
        strength = (1.6 if word == 'L' else 1.31) if spaced else 1.85
        if not spaced and len(s) == 1 and previous.isalpha():
            strength += 0.8 if previous in CONSONANT_L else 0.15
            if previous == 'm':
                strength += 0.55
    elif plain.endswith('l') and plain[-2] in CONSONANT_L:
        strength = CONSONANT_L[plain[-2]]
        if word[-1] == 'L':
            strength *= 1.19
        elif word[0].isupper():
            strength *= 0.78
        if n == 3:
            strength *= 0.96 if plain[0] in 'aeiou' else 0.77
        elif n > 3:
            strength *= 0.64 if n == 4 else 0.24
        strength *= 0.75 if spaced else 1
        strength *= 0.82 if len(s) > len(word) else 1
        if n > 3 and plain.endswith('irl'):
            strength *= 0.1
    elif plain.endswith('l') and plain[-2] in VOWEL_L:
        strength = VOWEL_L[plain[-2]]
        if not spaced and n == 3:
            strength += 0.55 if plain[0] == 'r' else 0.6 if plain[0] in 'aeiou' else 0
        if plain != low:
            strength = max(strength, 0.85)
        strength *= (2 / n) ** 1.5 * (0.3 if spaced else 1)
    elif plain.endswith('ll') and n <= 3 and not spaced:
        strength = 0.25 if word[-1] == 'l' else 1.0
    elif low in ('ł', 'л', 'λ', 'ل', 'ल', 'ล'):
        strength = 0.3 if low == 'λ' and spaced else 0.8
    elif 1 < len(low) <= 3 and low.endswith('л'):
        strength = 0.65 if low[-2] == 'у' else 0.05 if low[-2] in 'аеёиоуыэюя' else 1.0
    elif len(low) == 2 and low.endswith('ل'):
        strength = 0.2 if low[0] == 'ا' else 0.6
    elif len(low) == 1 and '\uac00' <= low <= '\ud7a3':
        # A Hangul syllable with final rieul, excluding accusative particles.
        final_rieul = (ord(low) - 0xac00) % 28 == 8
        if final_rieul and low not in ('을', '를'):
            strength = 0.6
    if low in COMPUTING:
        strength = COMPUTING[low]
        if s.startswith('.'):
            strength *= 0.5 if low == 'yaml' else 0.8
    return (doc, raw[-1:].lower()), -float(strength)

"""A marker for document openings and capitalized pieces of compound names.

Openings are positive, especially capitalized words and heading markers.
Inside documents, the strong signal is a capitalized piece continuing an
unspaced alphabetic name (camel case). It grows with earlier capitalized
pieces and gets an extra boost within the first unspaced word.
The trailing name is limited to 100 letters. A separator ends it; document
boundaries reset all state. The first four following positions receive a
small decaying boost; other tokens are predicted near zero.
"""
import re

READS = ()
WORD_END = re.compile(r'[A-Za-z]+\Z')
CAPITAL_PART = re.compile(r'[A-Z][a-z]+')
DIRECTIVES = set('package import from export using'.split())


def opening_value(token, title):
    if token.startswith('<|'):
        return 0.40
    if token.isspace():
        return 0.60
    if token[:1].isspace():
        return 0.20 if token.strip()[:1].isalnum() else 0.42
    if title:
        return 1.33 + 0.085 * min(len(token), 8)
    if token.isascii() and token[:1].isupper():
        return 0.77 if len(token) == 1 else 0.53
    if token[:1].isdigit():
        return 0.31
    if token[:1].islower():
        if token in DIRECTIVES:
            return 1.45
        return 0.42 if token.isascii() else 0.19
    if token[:1].isalpha():
        return 0.63 if token[:1].isupper() else 0.24
    if token.startswith('#'):
        return 2.26 if set(token) == {'#'} else 0.99
    if token.startswith(('/*', '//')):
        return 0.84 if '\n' in token else 1.09
    if token.startswith(('"', "'", '<?')):
        return 0.72
    if token[:1] in '(|-':
        return 0.65
    if token.startswith('*'):
        return 0.70
    return 0.32


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, word, first_word = 0, '', True
    else:
        _, position, word, first_word = carry
        position += 1
    title = (token.isascii() and token.isalpha()
             and token[:1].isupper() and not token.isupper())
    if position == 0:
        value = opening_value(token, title)
    else:
        value = -0.0034
        if title:
            value -= 0.030
            if word:
                capitals = min(len(CAPITAL_PART.findall(word)), 3)
                value += 0.234 + 0.015 * min(len(token), 8) + 0.221 * capitals
                if word.isupper():
                    value -= 0.155
                if len(word) == 1:
                    value -= 0.259
                if first_word:
                    value += 0.712
        elif token.startswith(('.', '_')) and len(token) > 1:
            value -= 0.020
        if position < 5:
            value += (0.043 if token[:1].isspace() else 0.096) / position

    ending = WORD_END.search(word + token)
    word = ending.group()[-100:] if ending else ''
    first_word = first_word and token.isascii() and token.isalpha()
    return (doc, position, word, first_word), float(value)

programs.haiku:
"""Candidate 6: a Titlecase word piece glued onto a preceding lowercase letter (a CamelCase
identifier's later part, e.g. the "Error" of ParseError) fires, most for common code nouns.
At the first token of a document it fires strongly if the token is Titlecase or a code opener."""

READS = ()

CODE_NOUNS = set("""
Error Errors Exception Handler Helper Result Results Response Request Manager Impl
Wrapper Source Format Factory Builder Listener Callback Parser Parse Service Provider
Adapter Controller Model View Config Options Info Element Property Field Value Values
Command Operation Reference Pair Entry Client Server Context Template Validator Node
State Mode Kind Log Writer Reader Item Items Struct
""".split())

CODE_OPENERS = {"#", "##", "package", "#include", "//", "import", "using", "def", "#!/"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    titlecase = len(cur) > 1 and cur[0].isupper() and cur[1].islower()
    if new_doc:
        # The first token of a document has no context: its response is set by the token alone.
        if titlecase:
            return None, 1.65
        if cur in CODE_OPENERS:
            return None, 1.9
        return None, (0.25 if cur[:1] == " " else 0.42)
    if not titlecase:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if prev and prev[-1].islower():
        # glued onto a lowercase word: a later part of an identifier
        return None, (0.75 if cur in CODE_NOUNS else 0.45)
    return None, 0.0

"""Layer-0 MLP down-projection component 4106.

Concept: a word-level "usefulness / need" detector. It is positive on words that
evaluate something as good, useful, needed or necessary (good, excellent, useful,
helpful, advantage, necessary, needed, used, "make sense"), and negative on a few
nouns such as "time" (as in "at the same time"), "area", "region", "thing",
"subject", and the figure label "FIG". Every other token gives 0.

The program reads only the newest token. It is a short word list, not a model of
the network: it captures the main positive and negative tokens, not their context.
"""

READS = ()

USEFUL_WORDS = {"good", "useful", "excellent", "helpful", "advantage",
                "necessary", "needed", "used", "sense"}
NEGATIVE_WORDS = {"time", "area", "region", "thing", "subject", "fig", "times"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in USEFUL_WORDS:
        value = 0.8
    elif word in NEGATIVE_WORDS:
        value = -0.4
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A sparse word-level sketch of this component's rare signed responses.

It treats time and figure references as negative, place/area nouns as negative,
and positive evaluation and usefulness words as positive. Unrecognized tokens
are assigned zero, so this is only a rough lexical sketch.
"""

READS = ()

TIME_WORDS = {"time", "times", "время"}
FIGURE_LABELS = {"fig", "figs", "figure", "figures"}
PLACE_WORDS = {"place", "area"}
FAVORABLE_WORDS = {
    "good", "excellent", "helpful", "useful", "effective",
    "necessary", "needed", "advantage",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in TIME_WORDS:
        return None, -0.55
    if word in FIGURE_LABELS:
        return None, -0.5
    if word in PLACE_WORDS or word == "subject":
        return None, -0.4
    if word in FAVORABLE_WORDS:
        return None, 0.45
    if word in {"part", "used", "sense"}:
        return None, 0.5
    return None, 0.0

programs.haiku:
"""Touching, contact and access: the component fires on words about physical or personal
contact ("contact", "touch", in any language), more weakly on words about access, exposure
or dealing with something ("access", "exposure", "encounter", "involved", "face"), and on
"with" (weakly by default, strongly when it follows such a word, as in "contact with",
"dealing with", "interact with")."""

READS = ()

CONTACT = {"contact", "contacts", "contacting", "contacted", "touch", "touches", "touched",
           "touching", "碰", "触", "觸", "chạm", "kontakt", "接触", "-contact", "<contact"}
RELATED = {"access", "accessible", "exposure", "exposed", "encounter", "encountered", "encounters",
           "proximity", "directly", "reach", "reached", "soil", "involve", "involved", "involves",
           "involving", "face", "faced", "deal", "dealing", "涉及", "xúc"}
WITH_AFTER = {"contact", "contacts", "dealing", "deal", "border", "connection", "interaction",
              "interact", "familiar", "encounter", "involved", "face", "communicate", "engage"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in CONTACT:
        return None, 3.5
    if word in RELATED:
        return None, 1.0
    if word == "with":
        prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
        return None, 1.5 if prev in WITH_AFTER else 0.5
    return None, 0.0

programs.luna:
"""Sketch a first-layer signal for being with, contacting, or encountering.

“With” has a modest, fairly regular response; words for direct contact and
access can produce a much larger one. This lexical sketch leaves most tokens
at zero rather than trying to reproduce all context-dependent variation.
"""

READS = ()


def step(carry, prefix, upstream):
    word = "".join(ch for ch in prefix.token_strings[-1].lower() if ch.isalpha())

    if word == "with":
        return None, 0.57

    if word == "contact":
        return None, 5.1
    if word.startswith("contacts"):
        return None, 3.5
    if word.startswith("contact") or "контакт" in word:
        return None, 3.5
    if "觸" in word or "触" in word:
        return None, 5.5
    if word.startswith("touchscreen"):
        return None, 1.8
    if word.startswith("touch"):
        return None, 5.0 if word.startswith("touching") else 4.5
    if word.startswith("chạm"):
        return None, 2.3
    if "接" in word:
        return None, 0.7
    if "접" in word:
        return None, 1.4
    if word.startswith(("gặp", "rencontre")) or "遇" in word:
        return None, 1.1
    if word.startswith("proximity"):
        return None, 2.2
    if word.startswith("encounter"):
        return None, 1.7
    if word.startswith("access"):
        value = 0.65 if word.startswith(("accessible", "accessibil")) else 1.1
        return None, value
    if word.startswith(("expos", "contaminat")) or "污染" in word:
        return None, 1.2 if word.startswith("expos") else 1.6
    if word == "directly":
        return None, 1.1
    if "直接" in word:
        return None, 0.7
    if word.startswith("involv"):
        return None, 1.0 if word == "involve" else 0.65
    if word in ("face", "faces", "faced", "facing") or word.startswith("affect"):
        return None, 0.6
    if word.startswith("reach"):
        return None, 0.6 if word == "reach" else 0.35
    if word.startswith("engag"):
        return None, 0.65
    if word == "to" and len(prefix.token_strings) > 1:
        previous = "".join(
            ch for ch in prefix.token_strings[-2].lower() if ch.isalpha()
        )
        if previous.startswith(("access", "expos")):
            return None, 0.9

    return None, 0.0

programs.sol:
"""Underscore/index fragments, not underscores inside ordinary word tokens.

The next token after a separate underscore is strong, especially in paths and
inline code. Double underscores weaken the response. Mathematical superscripts
are weaker, and fused braces change the amplitude. Spaces usually end the signal.
"""
READS = ()

# Syntax immediately before the underscores.
INTRODUCTION_BOOST = {
    "/": 1.0,
    "`": 1.6,
    '"': 0.4,
    "'": 0.4,
    "$": 0.5,
    ".": 0.25,
    "{": 1.1,
    "*": 1.0,
    "\\": -0.5,
}


def response(previous, token):
    if not previous or not token:
        return 0.0
    if previous.endswith("_"):
        root = previous.rstrip("_")
        count = len(previous) - len(root)
        if count >= 4:
            return 0.0  # A drawn horizontal line, rather than a name.
        if token.lstrip().startswith("_"):
            return -0.15
        if token[0].isspace():
            return 0.3
        if token.startswith("{\\"):
            return 3.9
        if token.startswith("{{"):
            return 2.4
        if token[0] in "{+-" or token == "\\":
            return 3.2
        if not token[0].isascii() or not token[0].isalnum():
            return 0.4
        # HTML's reserved target name for a new browsing context.
        if token == "blank":
            return 7.2
        value = 2.2 - 0.6 * (count - 1)
        value += INTRODUCTION_BOOST.get(root[-1:], 0.0)
        return value + (0.25 if token.isdigit() else 0.0)
    if previous.endswith("_{"):
        if token == "\\":
            return 2.5
        return 1.2 if len(token) == 1 else 0.7
    if previous.endswith("^{"):
        return 0.2
    if previous.endswith("^"):
        if previous.endswith("^^") or token.startswith("^"):
            return 0.0
        return 1.0 if token[0].isalnum() or token[0] in "{(*+-" else 0.25
    if previous.endswith("_\\"):
        return 1.3 if token[0].isalpha() else 0.1
    if previous.endswith("^\\"):
        return 0.8
    if previous.endswith("^{-") and token.isdigit():
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    return (doc, token), response(previous, token)

programs.haiku:
"""Candidate 6: the first piece of a subscript, superscript or underscore-joined name.

Fires on the token right after a marker, when that token is attached to the marker
(no space before it):
  - an underscore that joins identifier pieces (`NAME_1`, `__init__`, `__tests__`, `._x`) : strong
  - a LaTeX subscript opener (`_{i}`, `_\\text`) : medium
  - a caret (`x^2`) : medium, and `^{` (x^{2}) : almost none
Digits fire more than letters after the same marker. Long rows of underscores (blank
lines, `_____`) do not count. Everything else is 0.
"""

READS = ()

DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    cur = prefix.token_strings[-1]
    if cur == "" or cur[0].isspace() or cur.strip("_") == "":
        return None, 0.0
    digit = all(ch in DIGITS for ch in cur)
    if prev.endswith("_"):
        if prev.strip("_") == "" and len(prev) > 2:
            return None, 0.0
        v = 2.2 if digit else 1.8
    elif prev.endswith(("_{", "_\\")):
        v = 1.3
    elif prev == "^":
        v = 0.95 if digit else 0.7
    elif prev.endswith("^{"):
        v = 0.2
    else:
        v = 0.0
    return None, float(v)

programs.sol:
"""Relative and demonstrative tokens, with a local grammatical distinction.

The main response is to 'which': positive after a preposition, negative
otherwise, especially in comma-separated relative clauses. 'Whom' has a
similar preposition effect. Capitalized demonstratives are negative.
Smaller lexical responses cover related pronouns in several languages.
Only the preceding token is remembered; documents reset that memory.
"""
READS = ()

# Preposition + 'which' strengths, measured on training text.
PREPOSITIONS = {
    'of': 1.4, 'to': 4.0, 'for': 4.5, 'in': 6.3,
    'at': 5.8, 'on': 4.7, 'by': 5.4, 'with': 5.0,
    'from': 5.6, 'through': 6.0, 'under': 6.2, 'upon': 5.6,
    'during': 5.6, 'within': 4.8, 'over': 4.9, 'after': 4.3,
    'into': 4.3, 'against': 6.1, 'around': 3.1, 'among': 3.6,
    'before': 2.6, 'between': 2.8, 'without': 2.5, 'about': 2.3,
    'beyond': 3.7, 'along': 5.0,
}
QUESTION_VERBS = {
    'know', 'determine', 'decide', 'ask', 'see', 'check', 'identify',
    'choose', 'select', 'wonder', 'specify', 'find', 'explain', 'consider',
}
PRONOUNS = {
    'who': -0.1, 'whom': 0.6, 'whose': 0.55,
    'que': 0.22, 'qui': -0.8, 'cui': 2.0,
    'quel': 2.1, 'quelle': 1.6, 'quale': 1.2, 'quali': 0.65,
    'quoi': 1.7, 'yang': -1.0, 'dem': 0.41, 'denen': 1.4,
    'который': -0.67, 'которая': -0.5, 'которое': -0.55,
    'которые': -0.68, 'которых': 3.1, 'которой': 2.0,
    'которого': 2.3, 'котором': 2.15, 'которым': 1.5, 'чего': 1.6,
    'This': -0.93, 'These': -0.43, 'That': -0.2,
    'these': 0.14, 'those': 0.11, '这': -1.3, '這': -0.87,
}
COMMA_RESPONSE = {
    'which': -3.2, 'who': -0.31, 'whom': -0.23, 'whose': 0.32,
    'que': -0.25, 'qui': -1.12, 'cui': 0.0,
}
START_RESPONSE = {'which': -0.97, 'Which': -0.34, 'This': -1.08, 'whom': 1.6}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip()
    prev = previous.strip().lower()
    value = PRONOUNS.get(word, 0.0)

    if word in {'which', 'Which'}:
        value = -1.8 if word == 'Which' else -2.3
        if prev in PREPOSITIONS:
            value = PREPOSITIONS[prev]
            if word == 'Which':
                value *= 0.5
        elif word == 'which' and prev == '(':
            value = -3.2
        elif word == 'which' and prev in QUESTION_VERBS | {'and', 'or', 'one', 'those'}:
            value = -1.3
        elif word == 'which' and prev == 'that':
            value = -0.5
    elif word == 'whom' and prev in PREPOSITIONS:
        value = PREPOSITIONS[prev] + 0.5
        value = {'of': 2.46, 'in': 5.4, 'from': 5.1,
                 'on': 4.5, 'for': 4.7}.get(prev, value)
    elif word in {'who', 'whose'} and prev in PREPOSITIONS:
        value = 0.8 if word == 'who' else 1.7
    elif word == 'this':
        value = -0.12
        if prev in PREPOSITIONS:
            value = 0.27
            value = {'of': 0.01, 'by': 0.09, 'about': 0.08,
                     'during': 0.46, 'from': 0.35}.get(prev, value)
            if previous.strip()[:1].isupper():
                value += 0.18
        elif any(c in previous for c in ',;:=)'):
            value = -0.25
    elif word in {'This', 'These', 'That'} and not raw.startswith(' '):
        value += 0.12
    elif word == 'most' and prev == 'at':
        value = 0.98

    if ',' in previous and word in COMMA_RESPONSE:
        value = COMMA_RESPONSE[word]
    if not previous:
        value = START_RESPONSE.get(word, value)
    return (doc, raw), float(value)

programs.haiku:
"""Relative-pronoun detector for layer 0, MLP down_proj, component 4110.

The component is a "which / whose / This" detector. Its sign depends on what comes right
before the word:
- "which" that opens a non-restrictive clause after a comma (", which") is strongly
  NEGATIVE (about -3.2); after a noun ("a network which") it is about -2.4.
- "which" right after a preposition ("at which", "of which", "in which") is strongly
  POSITIVE (about +2.5, once +5.5).
- "whose" (as in "in whose name") is positive (about +1.7).
- A sentence-initial "This" is about -0.9, a sentence-initial "Which" about -1.6.
Every other token predicts 0.
"""

READS = ()

PREPOSITIONS = {
    "of", "at", "in", "on", "to", "for", "from", "by", "with", "into", "through",
    "during", "within", "among", "between", "under", "over", "about", "after",
    "before", "across", "along", "against", "without", "upon",
}
SENTENCE_END = (".", "!", "?", ":", "\n")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.token_ids) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc:
        prev_raw = prefix.token_strings[-2]
    else:
        prev_raw = ""
    prev = prev_raw.strip().lower()
    at_start = prev_raw.strip() == "" or prev_raw.endswith(SENTENCE_END)
    value = 0.0
    if tok == "which":
        if prev in PREPOSITIONS:
            value = 2.5
        elif at_start:
            value = -1.6
        elif prev_raw.endswith(","):
            value = -3.2
        else:
            value = -2.4
    elif tok == "whose":
        value = 1.7
    elif tok == "this" and at_start:
        value = -0.9
    return carry, float(value)

"""Negative bigram detector for fixed phrases built on 'the'.

The component pushes its output strongly negative on the word that directly follows
'the' / 'The' when that word completes a stock phrase: 'the way', 'the same', 'the only',
'the case', 'the above', 'the fact', 'the need', 'the thing', 'the reason', ... It also
fires on a word-piece that completes a word starting with 'The' when split off
('The' + 'ore' -> Theorem, 'The' + 'o' -> Theodore, 'The' + 'il' -> Theil, ...).
Elsewhere it is near zero, except a weak negative on a few of the same words used
without 'the' (e.g. 'a way', 'this way').
"""

READS = ()

# mean activation of the word right after "the", by word (negative = fires)
AFTER_THE = {
    " way": -3.9, " same": -2.1, " only": -1.5, " case": -1.2, " thing": -1.5,
    " need": -1.2, " resulting": -1.2, " reason": -1.1, " above": -1.0, " like": -1.0,
    " kind": -1.2, " ways": -1.5, " idea": -0.9, " fact": -0.8, " more": -0.8,
    " corresponding": -0.7, " one": -0.5, " form": -0.4, " day": -0.4,
}
# the same word used after another determiner or without a determiner
OTHER_WAY = {" way": -0.3, " same": -0.3}
THE = {"the", "The", "THE"}
WORD_PIECE = -3.0  # a no-space piece right after "the": Theorem, Theology, Theodore


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    before = prefix.token_strings[-2].strip()
    word = prefix.token_strings[-1]
    if before in THE:
        if word in AFTER_THE:
            return None, AFTER_THE[word]
        if word[:1].isalpha():
            return None, WORD_PIECE
        return None, 0.0
    return None, OTHER_WAY.get(word, 0.0)

programs.sol:
"""Sparse lexical responses to small plural quantities, 'how', and geometry.

The largest negative responses are several/few and their translations,
particularly Chinese 几/幾. Longer Chinese count phrases have weaker responses.
The preceding word distinguishes 'last few' from 'a few'. Words not covered
by these classes receive zero; small miscellaneous responses are omitted.
"""
READS = ()

QUANTITIES = {
    'couple': -0.87, 'couples': -0.52, 'handful': -1.11,
    'dozens': -1.05, 'quelques': -1.35, 'plusieurs': -1.83,
    'algumas': -0.70, 'alguns': -0.72, 'algunos': -0.45,
    'varias': -0.97, 'varios': -1.33, 'einige': -0.62,
    'paar': -0.66, 'beberapa': -1.87, 'birkaç': -2.06,
    '여러': -1.99, 'vài': -1.92, 'mấy': -3.08,
    'いく': -1.62, 'いくつか': -2.60,
    '一些': -0.45, '有些': -0.51, '多少': -1.77,
}
FEW_CONTEXT = {
    'last': -2.05, 'first': -1.80, 'past': -1.60,
    'every': -1.68, 'the': -1.48, 'next': -1.42, 'too': -0.65,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry and carry[0] == doc else ''
    value = QUANTITIES.get(word, 0.0)
    if word == 'several':
        value = -3.2 if token == 'Several' else -2.9
    elif word == 'few':
        value = FEW_CONTEXT.get(prev, -1.18)
    elif word.strip('/-_') == 'how':
        value = -0.78 if token.strip() == 'How' else -0.88
    elif '几' in word or '幾' in word:
        w = word.replace('幾', '几').replace('個', '个')
        if '几率' in w:
            value = 0.0  # Probability, not a quantity.
        elif '几乎' in w:
            value = -1.4 * 0.72 ** (len(w) - 2)  # Almost.
        elif w == '几':
            value = -7.2 if word == '幾' else -8.7
            if prev.endswith('好'):
                value = -5.8
        elif w == '几何':
            value = -3.0  # Geometry.
        elif w.startswith('几'):
            value = -4.7 * 0.8 ** (len(w) - 2)
            if w == '几个':
                value = -4.9 if word == '幾個' else -6.0
        elif w == '了几':
            value = -6.35
        else:
            value = -4.0 if w.endswith('个') else -2.1
    elif word.startswith('нескол'):
        value = -2.8  # Russian several, including inflections.
    elif word in {'geometry', 'geometric', 'geometrical', 'geomet'}:
        value = -1.45 if word == 'geometric' else -1.1
    return (doc, word), value

programs.haiku:
"""Layer-0 MLP unit 4112: a detector for vague-quantity words.

The unit goes negative on the word that opens an indefinite amount ("some number
of ..."). Strongest: Chinese 几 / 幾 ("a few", "how many"), then "several",
then "few", "a couple (of)", "a handful", "how" (as in "how many / how much"),
and the same words in other languages (plusieurs, quelques, varios, несколько,
mấy, 多少, いくつ). "many", "much", "some" and "lots of" do not fire it.
Everywhere else the prediction is 0. The value of each group is its typical
activation, not a fitted number. The unit depends only on the current word,
plus the previous word for "of" after "couple".
"""

READS = ()

# Typical activation for each group of words (most negative first).
CHINESE_JI = -6.0      # 几 / 幾: 几个, 几天, 有几个, 了几 ... 
SEVERAL = {"several", "несколько", "нескольких", "mấy"}
FEW = {"few", "couple", "handful", "dozen", "plusieurs", "quelques", "varios", "varias",
       "algunas", "algumas", "einige", "alcuni", "vài", "若干"}
HOW_MANY = {"how", "多少", "いくつ", "いくつか", "いく"}
SMALL = {"一些", "些", "两个", "两", "兩個", "两张", "三个", "十个", "多个", "不少"}
PREV_QUANTITY = {"couple", "few", "several"}


def value_of(word):
    if "几" in word or "幾" in word:
        return CHINESE_JI
    if word in SEVERAL:
        return -3.0
    if word in FEW:
        return -1.2
    if word in HOW_MANY:
        return -0.9
    if word in SMALL:
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = value_of(word)
    if word == "of" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in PREV_QUANTITY:
            value = -0.6
    return carry, float(value)

programs.sol:
"""A detector of qualified names and explicit boundaries.

It fires mainly on a period fused to a name: file suffixes, domains, and
object members.  Abbreviations and sentence starters are weaker.  A name
split from its accessor has a smaller response.  Possessive compounds,
access operators, and dialogue/control tags supply secondary triggers.
Only the previous token is remembered, resetting at document boundaries.
"""
READS = ()

MEDIA_SUFFIXES = set('png jpg jpeg gif svg ico pdf zip gz tar mp3 mp4 wav'.split())
DOMAIN_SUFFIXES = set('com org net edu gov io'.split())
SENTENCE_STARTERS = set(
    'The This That These Those It He She We They You In On At For And But '
    'A An There As To However'.split()
)
OUTPUT_NAMES = set('print println printf Printf Println log out Errorf'.split())
JAPANESE_PARTICLES = set('ので のは のが のに のを のです のだ のか のと のも'.split())
BOUNDARIES = {
    '<|im_start|>': 1.97,
    '<|im_end|>': 1.65,
    '<think>': 1.58,
    '</think>': 3.95,
    '<tool_call>': 2.26,
    '</tool_call>': 1.42,
    '<tool_response>': 1.67,
    '</tool_response>': 2.87,
}


def qualified_name(word, previous):
    """The part of a token following its initial period."""
    p = previous.strip()
    if (word == 'g' and p.lower() == 'e') or (word == 'e' and p.lower() == 'i'):
        return -0.09                    # e.g. and i.e.
    if len(word) == 1 and word.isupper():
        if word == 'S' and p == 'U':
            return 0.25                # U.S.
