"""Approximate small lexical biases and a rare document-initial response.

This is a partial approximation, not a unified semantic detector. It assigns
near zero to unrecognized tokens. In ordinary context it assigns negative
values to indefinite quantities and completeness words, and positive values
to temporal-order and help words.
A space-prefixed inverted exclamation mark is strongly positive specifically
at a document's first token. All coefficients summarize training measurements.
"""
READS = ()

LEXICAL_CLASSES = (
    ("any some other another", -0.040),       # indefinite choice
    ("more most less few enough", -0.024),   # comparative quantity
    ("completely entirely fully totally wholly", -0.082),
    ("before after", 0.044),                 # temporal ordering
    ("also too furthermore moreover additionally", 0.023),
    ("only just simply merely", 0.030),      # restriction
    ("help helps helped helping", 0.063),
    ("package packages", 0.087),
    ("null nil", -0.077),                    # null literals
    ("true", -0.048),                        # truth literal
)
LEXICAL_CLASSES = tuple((frozenset(words.split()), value)
                        for words, value in LEXICAL_CLASSES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    s = prefix.token_strings[-1]
    t = s.strip()
    spaced = s.startswith(" ")
    value = -0.0003
    if first and t == "¡":
        value = 0.546 if spaced else 0.126
    elif s == "\r":
        value = 0.081
    elif not t:
        value = -0.060 if first else (0.009 if "\n\n" in s else 0.0)
    elif t in ("¡", "¿"):
        value = -0.036
    elif t == "··":
        value = 0.095
    elif t == "$":
        value = 0.044 if spaced else -0.009
    elif t in ("∈", "∉"):
        value = 0.140
    elif t.startswith("/*") or t.startswith("*/"):
        value = 0.048
    elif t in ("\\(", "\\[", "\\_", "\\)"):
        value = 0.082
    elif t in (".py", ".php"):
        value = -0.073
    elif t in ("+", "*"):
        value = (0.0 if t == "+" else 0.028) if spaced else -0.024
    elif first:
        if t.lower() in ("the", "a", "an"):
            value = 0.064 if t[0].isupper() else -0.056
        else:
            value = -0.014
    else:
        for words, weight in LEXICAL_CLASSES:
            if t.lower() in words:
                value = weight * (0.65 if t[0].isupper() else 1.0)
                break
        else:
            if t.startswith(".") and len(t) > 1 and t[1].isalpha():
                value = -0.014
            elif len(t) == 1 and "a" <= t <= "z" and not spaced:
                value = -0.017 if t in "aeiou" else -0.007
    return doc, float(value)

