"""layers.0.mlp.down_proj:4114 - a weak, token-level component.

What it does: it is a small, diffuse signal that is set mostly by the identity of the
current token, not by context. Its activation is usually within +-0.03 of zero. The
clearest systematic pattern is on programming-language identifiers: CamelCase names
(`IsDBNull`, `StringBuilder`) and dotted member names (`.IOException`, `.stereotype`)
push the activation negative, on average about -0.014. Math limit and operator tokens
(`lim`, `max`, `∈`) and Japanese kana tokens lean slightly positive.

This program predicts those class means for the current token and 0 elsewhere. It uses
no other tokens, so it is a readable explanation of the leading pattern, not of most of
the variance. The current token only; earlier tokens are not needed.
"""

import re

READS = ()

MATH_WORDS = {"lim", "limsup", "liminf", "max", "min", "sup", "inf", "log", "exp",
              "det", "dim", "ker", "sin", "cos", "tan"}
MATH_SYMBOLS = set("∈∞→∑∫≤≥≠±×÷√∂∇")

CODE_IDENT = re.compile(r"[a-z][A-Z]|\.[A-Za-z_][A-Za-z0-9_]*")


def is_code_identifier(text):
    return CODE_IDENT.search(text) is not None


def is_math(text):
    return text.strip() in MATH_WORDS or any(ch in MATH_SYMBOLS for ch in text)


def is_kana(text):
    return any("぀" <= ch <= "ヿ" for ch in text)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if is_code_identifier(text):
        value = -0.0135
    elif is_math(text):
        value = 0.002
    elif is_kana(text):
        value = 0.003
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Coarse spelling and document-opening response.

The positive contextual feature is a word continuing after an nt-ending
piece, especially ent/ant (also Cyrillic ент/ант). Opening capitalized text
and indentation instead predict a negative response; chat openers predict
positive. Small offsets describe token shape, Chinese characters or hiragana, chat
delimiters, and the gradual rise away from the document's start. State resets
at every document boundary.
This averages over the component's word-specific variation.
"""
import math

READS = ()


def east_asian(word):
    return any('\u4e00' <= c <= '\u9fff' or
               '\u3040' <= c <= '\u309f' for c in word)


def opening(token, word):
    if token == '<|im_start|>':
        return 0.221
    if not word:
        if '\n' in token:
            return -0.123
        return -0.179 if '\t' in token else -0.25
    if word.isdecimal():
        return 0.084
    if word.isascii() and word.isalpha():
        spaced = token[0].isspace()
        if word.isupper():
            return -0.105 if spaced else -0.148
        if word.istitle():
            value = -0.254 if len(word) <= 3 else -0.179
            return value + (0.06 if spaced else 0.0)
        if spaced:
            return -0.025
        if len(word) == 1:
            return 0.100
        return 0.003 if len(word) <= 3 else -0.075
    if any('\u0400' <= c <= '\u052f' for c in word):
        return -0.178 if word[0].isupper() else -0.079
    if word.startswith('('):
        return 0.165
    if word.startswith('#'):
        return -0.150
    return -0.021 if east_asian(word) else -0.050


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    first = carry is None or carry[0] != doc
    age = 0 if first else carry[2] + 1
    if first:
        value = opening(token, word)
    else:
        value = 0.006
        if east_asian(word):
            value = 0.035
        elif not word or word.isdecimal():
            value = 0.002
        elif word.isascii() and word.isalpha():
            value = 0.014 if len(word) >= 8 else 0.004
            if word.islower() and not token[0].isspace() and len(word) >= 4:
                value = 0.014
        elif word.isascii() and not any(c.isalnum() for c in word):
            value = 0.001
        if token == '<think>':
            value = 0.140
        elif token in ('</think>', '<|im_end|>'):
            value = -0.039
        elif token == '<|endoftext|>':
            value = 0.018
        previous = carry[1].strip().casefold()
        if previous.endswith(('nt', 'нт')):
            joined = token[:1].isalpha()
            if joined and previous.endswith(('ent', 'ant', 'ент', 'ант')):
                value += 0.27 if len(previous) == 3 else 0.13
            elif joined and not previous.endswith('int'):
                value += 0.055
            elif token[:1] in ('-', '_') and any(c.isalpha() for c in token):
                value += 0.09
            elif not joined:
                value += 0.015
        value += 0.004 - 0.013 * math.exp(-age / 90.0)
    return (doc, token, age), float(value)

"""A negative signal when a word continues after an 'an'-like fragment.

Short fragments ending in 'an' give the strongest response. For Latin text,
longer fragments and continuations weaken it; case also modulates the value.
The Cyrillic 'ан' and Arabic 'ان' spellings also count; other n-endings give a
weak response. A word boundary mostly suppresses the signal. English 'an'
followed by a spaced vowel-initial word gets a small positive value instead.
"""
import unicodedata

READS = ()


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def script(char):
    name = unicodedata.name(char, '')
    for language in ('LATIN', 'CYRILLIC', 'ARABIC'):
        if language in name:
            return language
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    stem = previous.strip()
    lower = unaccent(stem)
    length = max(1, len(stem))
    value = 0.0

    if token and (token[0].isalpha() or
                  unicodedata.category(token[0]).startswith('M')):
        alphabet = script(token[0])
        if alphabet == 'LATIN' and lower.endswith('an'):
            value = -0.27 - 2.9 / length + 0.14 * min(len(token), 8)
            if lower == 'an':
                value += 0.20
            if stem[0].isupper():
                value -= 0.20
            if token[0].isupper():
                value += 0.36
            if unaccent(token[0]) in 'aeiou':
                value -= 0.10
            if len(token) == 1:
                value -= 0.07
            value = min(0.0, value)
        elif alphabet == 'CYRILLIC' and lower.endswith('ан'):
            value = min(0.0, 0.14 - 1.85 / length)
        elif alphabet == 'ARABIC' and lower.endswith('ان'):
            value = -0.46 - 0.62 / length
        elif (alphabet == 'LATIN' and 'an' in lower and
              len(lower) - lower.rfind('an') - 2 <= 2):
            value = min(0.0, 0.09 - 0.93 / length)
        elif (lower.endswith(('n', 'н')) and stem and
              script(stem[-1]) == alphabet):
            value = -0.08
    elif lower.endswith('an') and token:
        word = token.lstrip()
        if token[0].isspace() and word and word[0].isalpha():
            if lower == 'an':
                value = 0.07 if word[0].lower() in 'aeiou' else -0.02
        elif token[0] in "'’" or token[0].isdigit():
            value = -0.11

    return (doc, token), float(value)

