"""Predict a spelling-selective response, chiefly to short 'ie' fragments.

Fragments such as ier, ien and iet receive the strongest response. Extra
letters usually dilute it; view/field/yield and die-family spellings are
weak exceptions. Related vowel pairs receive smaller responses. Adjacent
tokens can jointly form a pair, but never across document boundaries.
This approximation leaves miscellaneous word-specific effects unmodeled.
"""
import unicodedata

READS = ()
BOUNDARY_VOWELS = {'ie': 1.55, 'ia': 0.8, 'io': 0.65,
                   'iu': 0.45, 'ye': 0.55, 'ue': 0.36}


def spelling(token):
    word = ''.join(c for c in unicodedata.normalize('NFD', token)
                   if not unicodedata.combining(c))
    word = word.strip().lower().lstrip('._-/(')
    i = word.find('ie')
    if i >= 0:
        if word.startswith(('view', 'field', 'yield')):
            return 0.05
        if word in ('die', 'died', 'dies', 'diet'):
            return 0.3 if word == 'die' else 0.6
        tail = word[i + 2:]
        if not tail:
            return 0.75 * 0.7 ** max(0, i - 1)
        # The consonant closing a short ie fragment controls its strength.
        strength = (3.05 if tail[0] in 'rnt' else
                    2.3 if tail[0] in 'lm' else
                    1.7 if tail[0] == 'd' else 1.05)
        if len(tail) > 1:
            strength *= (0.8 if tail[1] == 's' else
                         0.42 if tail[1] in 'aeiou' else 0.5)
            strength /= 1.0 + 0.3 * (len(tail) - 2)
        if i == 1 and tail == 'r' and word[0] in 'ph':
            return 2.85
        return strength * (1.0 if i == 0 else
                           0.6 if i == 1 else
                           0.23 if i == 2 else 0.03)
    for pair in ('ia', 'io', 'iu', 'ue'):
        i = word.find(pair)
        if i == 0:
            if word.startswith(('ial', 'ion')):
                return 0.1
            return 0.5 if len(word) > 2 or pair in ('iu', 'ue') else 0.05
        if i == 1 and word[0] not in 'qg':
            return 0.4
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = spelling(token)
    if previous and token:
        pair = previous[-1].lower() + token[0].lower()
        value += BOUNDARY_VOWELS.get(pair, 0.0) / (
            1.0 + 0.35 * max(0, len(token) - 2))
        # A preceding one-letter piece strengthens an ie fragment.
        if token.lower().startswith('ie'):
            onset = previous.strip()
            if len(onset) == 1 and onset.isalpha():
                value += 0.5
    return (doc, token), float(value)

"""A lexical addition detector, not an arithmetic calculator.

Predict large responses to 'add' word forms and Chinese 加, with weaker
responses to compounds and a few translations. Plus signs are strongest as
added-line markers, weaker as arithmetic or string-concatenation operators.
Also model single tabs, 'addition of', Korean 가 and Japanese が.
Most other tokens receive zero; their small token-specific responses are omitted.
