import re

READS = ()
CODE_WORD = re.compile(r'\b(return|const|let|var|def|class|function|else|int)\b')
ADD_FORMS = {'add': 1.59, 'adding': 1.66, 'added': 1.29, 'adds': 1.38,
             'addition': 1.04, 'additions': 1.04, 'additive': 0.91,
             'additives': 0.98, 'addon': 0.85, 'addons': 0.85}


def plus_response(token, tail):
    previous = tail[-1:]
    word = token.strip()
    if '+=' in token:
        return 0.6
    if word == '+++':
        return 0.49
    if '++' in token:
        return 0.05 if any(c in token for c in ');') else 0.17
    if token == '+\n':
        return 0.46
    if word != '+':
        return 0.12 if any(c.isalpha() for c in token) else 0.27
    if token == '+':
        if previous == '\n':
            return 0.73  # Added line in a patch.
        return 0.24 if previous.isalnum() else 0.43
    if previous in {'"', "'"}:
        return 0.35  # String concatenation.
    code = any(c in tail for c in '{};') or CODE_WORD.search(tail)
    if previous.isdigit():
        return 0.12 if code else 0.05
    return 0.21 if code else 0.09


