        if stem == 'add' and word[:1] in '._(':
            value = 1.43
        elif stem in {'added', 'adding'} and not token[:1].isspace():
            value = 0.55 if tail[-1:].isalpha() else 1.35
    elif stem.startswith('add') and not stem.startswith(('addr', 'additional')):
        value = 0.45
