        ending = prefix.text_prefixes[-1][-2:] if tail else word
        if ending in {'增加', '増加'}:
            value = 1.15
        elif ending in {'追加', '参加', '參加'}:
            value = 2.1
    elif word == '加以':
        value = 3.7
    elif word in {'加上', '再加上', '加大', '加之'}:
        value = 2.15
    elif word in {'加速', '加盟', '加息', '加州', '加拿'}:
        value = 0.85
    elif word.startswith('加') or word in {'添加', '更加', '愈加'}:
        value = 1.55 if len(word) == 2 else 0.7
    elif '加' in word:
        value = 0.03 if word in {'新加坡', '芝加哥'} else 0.58
    elif word in {'添', '增添'}:
        value = 1.1
    elif lower.startswith('добав') or lower == 'обав':
        value = 0.8 if lower == 'обав' else 1.2
    elif lower in {'ajout', 'adicion', 'thêm'} or word == '추가':
        value = 0.6
    elif word in {'가', 'が'}:
