        value = plus_response(token, tail)
    elif token == '\t':
        value = 0.05 if tail.endswith('\t') else (0.28 if tail[-1:].isdigit() else 0.21)
        if not tail:
            value = 0.075
    if word == 'of' and tail.rstrip().lower().endswith('addition'):
        value = 0.7
    return (document, (tail + token)[-200:]), value

