programs.sol:
"""Approximate a standalone-whitespace and end-of-document detector.

Text-bearing tokens get zero; the end-of-text marker gets a strong response.
Space and tab runs are stronger immediately after a newline. Space counts
one short of four-column alignment (3, 7, 11, ...) are especially strong.
Longer space-only runs also get an early-document boost. Nonbreaking spaces
and newline-bearing whitespace have separate length-based estimates.
The small space-width calibration uses character counts, not vocabulary ids.
"""
from math import log

READS = ()
SPACE_WIDTH = (
    0.0, 0.0, 0.36, 1.20, 0.82, 0.52, 0.37, 1.57,
    0.65, 0.33, 0.24, 1.32, 0.42, 0.12, 0.11, 1.26,
    0.49, 0.24, 0.41, 1.43, 0.91, 0.59, 0.78, 1.92,
)


def spacing(token, previous, age):
    new_line = previous.endswith(('\n', '\r'))
    spaces, tabs, nbsp = (token.count(c) for c in ' \t\u00a0')
    if nbsp:
        if spaces:
            value = 0.65 + 0.08 * min(nbsp, 2)
        elif nbsp % 2:
            value = min(1.45, 1.05 + 0.05 * (nbsp - 1))
        else:
            value = 0.4
        return value - 0.2 * bool(previous and previous.isspace())
    if tabs:
        if not spaces:
            value = 0.19 * tabs - 0.05 + 0.3 * (tabs >= 5)
            return value + (1.0 if new_line else
                            0.5 * bool(previous and previous.isspace()))
        if spaces <= 2:
            value = 0.22 + 0.05 * spaces
        elif spaces == 7:
            value = 2.0
        elif spaces % 4 == 3:
            value = min(3.0, 1.0 + 0.07 * spaces)
        else:
            value = 0.8 + 0.005 * spaces
        return value + 0.42 * (tabs - 1) + 1.3 * new_line
    if spaces == 1:
        return 0.76 * new_line
    if spaces < len(SPACE_WIDTH):
        value = SPACE_WIDTH[spaces]
        if new_line:
            value += 0.65 + (0.03 if spaces % 4 == 3 else 0.008) * spaces
    else:
        if spaces >= 64:
            value = 0.9
        elif spaces % 4 == 3:
            value = 2.4 + 0.95 * new_line
        else:
            value = 1.4 + 0.5 * new_line
    # Spacing signals are somewhat stronger near the beginning of a document.
    return value * max(0.7, 1.0 - 0.065 * log((age + 1) / 200))


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    age, previous = (carry[1], carry[2]) if carry and carry[0] == doc else (0, '')
    value = 0.0
    if token == '<|endoftext|>':
        value = 2.70 - 0.65 / (age + 1) ** 0.5
        value -= 0.1 * previous.endswith(('\n', '\r'))
    elif token and all(c in ' \t\u00a0' for c in token):
        value = spacing(token, previous, age)
    elif token and token.isspace():
        n, tabs = token.count(' '), token.count('\t')
        if n >= 3:
            value = 0.52 + 0.036 * n - 0.42 * (n < 20 and n % 4 == 3)
        if tabs > 1:
            value += 0.3 * tabs
    return (doc, age + 1, token), float(value)

