    "hardly": -1.9, "barely": -1.6, "semi": -1.5, "大约": -1.9, "将近": -1.9, "接近": -1.7,
}
HEDGE = {
    "approximately": -1.3, "roughly": -1.15, "essentially": -1.3, "somewhat": -1.4,
    "mostly": -1.2, "pretty": -1.2, "basically": -1.0, "largely": -0.85, "slightly": -0.7,
    "absolutely": -0.9, "seemingly": -0.9,
}
DEGREE = {
    "more": -0.8, "most": -0.9, "only": -0.85, "something": -1.0, "least": -1.0,
    "early": -0.9, "near": -0.86, "quite": -0.9, "-like": -0.9,
}
WEAK = {
    "much": -0.45, "less": -0.42, "half": -0.42, "exactly": -0.7, "highly": -0.46,
    "close": -0.39, "about": -0.2, "around": -0.25, "approx": -0.6, "approximate": -0.6,
    "closely": -0.6,
