programs.sol:
"""Approximate the component's large surface-syntax responses.

Literal doubled backslashes are strongly positive. Closing angle brackets
are positive, especially after type names, but not at the start of a line.
Unspaced punctuation after tabs, non-ASCII spaces, or a space followed
by a backslash is negative. Ordinary text gets a near-zero background.
The state remembers the previous token and consecutive trailing tabs;
it resets when the document changes. This omits smaller word-specific
responses rather than storing an arbitrary vocabulary table.
"""
READS = ()

# Familiar scalar types and the conventional type-parameter name T.
SCALAR_TYPES = {
    'String', 'string', 'Object', 'Integer', 'int', 'Long', 'long',
    'Double', 'double', 'Float', 'float', 'Boolean', 'bool', 'char', 'T',
}

AFTER_TAB = {
    '/': -0.44, '#': -0.49, '*': -0.55, '&': -0.72,
    '[': -0.45, ']': -0.32, '(': -0.24, ')': -0.39,
    '{': -0.25, '}': -0.22, '"': -0.32, "'": -0.30,
    ',': -0.35, '$': -0.30, '\\': -0.38, '<': -0.28, '@': -0.20,
    ':': -0.64, '?': -0.55, '-': -0.55, '>': -0.15,
}
AFTER_NBSP = {
    '`': -0.96, '-': -0.96, '+': -0.82, '=': -0.75,
    '|': -1.20, '>': -0.95, '*': -1.00, ':': -0.69,
    '#': -0.70, '[': -0.53, '(': -0.54, '@': -0.37,
    '\\': -0.58, '×': -0.51, '–': -0.77, '$': -0.42,
    '/': -0.88, '.': -0.65, '}': -0.60, '·': -1.45, '⋅': -1.20,
    '≤': -0.90, '±': -0.70, '−': -0.70,
}
AFTER_ESCAPE = {
    '[': -0.61, ']': -0.53, ')': -0.56, ',': -0.45,
    '*': -0.57, '>': -0.56, '{': -0.42, '}': -0.40,
    '"': -0.60, '#': -0.48, '-': -0.98, '&': -0.80,
    '$': -0.55, '!': -0.55,
}


def response(s, previous, start, tabs=1, initial_tab=False):
    if '\\\\' in s:
        core = s.strip()
        if s.endswith('\n') or core.endswith('.'):
            return 0.88
        if set(core) == {'\\'}:
            if s.startswith(' '):
                return 1.32
            if len(core) % 2:
                return 0.68
            return 1.54 if len(core) == 2 else 1.82
        return 1.27

    if '\xa0' in s and all(c in ' \xa0' for c in s):
        repeats = '\xa0' in previous
        if ' ' in s:
            return -0.88 if repeats else -0.12
        if len(s) > 1:
            return -0.49 if repeats else -0.11
        if start:
            return -0.53
        if repeats:
            return -0.23
        return -0.11 if previous.endswith(' ') else 0.15

    symbol = s[:1]
    if symbol:
        if '\xa0' in previous and symbol in AFTER_NBSP:
            if any(c.isalpha() for c in s):
                return 0.001
            value = AFTER_NBSP[symbol]
            return value * 0.54 if s == '`' else value
        if previous.endswith('\t') and symbol in AFTER_TAB:
            value = AFTER_TAB[symbol]
            if initial_tab:
                value *= 2.2
            if tabs > 1:
                value *= 1.50 if symbol in '/#{}' else 1.15
            if s.startswith('/*') or s.startswith('///'):
                value = -0.32
            if s.endswith('\n\n'):
                value *= 0.58
            if any(c.isalpha() for c in s):
                value *= 0.5
            return value
        if previous == ' \\' and symbol in AFTER_ESCAPE:
            value = AFTER_ESCAPE[symbol]
            return value * 0.65 if s.startswith('),') else value

    if s in ('right', 'ref', 'cite') and previous == ' \\':
        return -0.39
    if s in ('>', '>>'):
        if previous.endswith('\n') or previous.strip().endswith('cin'):
            return 0.03
        if previous.strip().lstrip('<') in SCALAR_TYPES:
            return 1.00
        if '<' in previous:
            return 0.96 if previous.lstrip().lstrip('<')[:1].isupper() else 0.83
        if previous.lstrip()[:1].isupper():
            return 0.67
        return 0.35 if previous.strip().isdigit() else 0.47
    if s in ('>>>', '>)', '>]', '>/'):
        return 0.035
    if s in ('＞', '›'):
        return 0.44
    if '>' in s and all(c in ' \r\n[]()"\'\\/>' for c in s):
        return 0.09 if '\n' in s else 0.08 if s.startswith(' ') else 0.38
    if s == '\x00':
        return -0.57 if previous.endswith(' ') else -0.08
    return 0.001



def normalize_spaces(text):
    # Hair spaces, thin spaces, and narrow no-break spaces share this role.
    return ''.join('\xa0' if c.isspace() and c not in ' \t\r\n\v\f'
                   else c for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, tabs, previous_start = ('', 0, False) if start else carry[1:]
    s = normalize_spaces(prefix.token_strings[-1])
    if not previous_start and '\ufffd' in previous and s[:1] in AFTER_NBSP:
        # Decode only in this rare case: a space split across byte-level tokens.
        last_character = prefix.text_prefixes[-2][-1:]
        if normalize_spaces(last_character) == '\xa0':
            previous = '\xa0'
    trailing = len(s) - len(s.rstrip('\t'))
    new_tabs = trailing + (tabs if s and set(s) == {'\t'} else 0)
    value = response(s, previous, start, tabs, previous_start)
    return (doc, s, new_tabs, start), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 4133: a token-level detector.

It writes a signed signal into the residual stream that tracks a few code and
markup punctuation tokens. Each rule looks at the current token and, for two
rules, at the tokens just before it:

* an escaped backslash: a token ending in an even run of two or four backslash
  characters (the token that stands for two backslashes inside a string literal
  such as "C:\\path") -> strongly positive; an odd run of three -> weakly positive;
* a closing angle bracket ">" (also ">>" or '\\">') that closes a generic or
  tag opened by "<" within the last 20 tokens (List<String>, <a href=...>)
  -> positive; a bare ">" with no opener nearby -> about zero;
* a punctuation or operator token with no leading space that comes right after
  a non-breaking space (U+00A0, typical of text pasted from web pages) -> strongly
  negative; right after a tab (indented code) -> negative;
* a bare non-breaking space -> slightly positive;
* the "//" comment marker and a "}" before a newline -> mildly negative.

Everything else is predicted as 0. The carry holds the last 20 token strings and
the document id, so the look-back resets at document boundaries.
"""

READS = ()

NBSP = "\xa0"
WINDOW = 20  # recent tokens to look back over for an opening "<"


def _trailing_backslashes(s):
    core = s.rstrip(" \n\t")
    return len(core) - len(core.rstrip("\\"))


def _is_symbol(s):
    """Punctuation or operator: not empty, not a letter/digit, no leading space."""
    return s != "" and not s[0].isalnum() and not s[0].isspace()


def step(carry, prefix, upstream):
    recent, doc = carry if carry is not None else ((), None)
    if prefix.document_ids[-1] != doc:
        recent, doc = (), prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    prev = recent[-1] if recent else ""
    value = 0.0
    n_bs = _trailing_backslashes(s)
    if n_bs >= 2:
        value = 1.5 if n_bs % 2 == 0 else 0.7
    elif s.endswith(">") and "<" not in s and any("<" in r and ">" not in r for r in recent):
        value = 0.6
    elif s in (">", ">>"):
        value = 0.06
    elif _is_symbol(s) and NBSP in prev:
        value = -0.8
    elif _is_symbol(s) and "\t" in prev:
        value = -0.25
    elif s == NBSP:
        value = 0.07
    elif s == "//":
        value = -0.2
    elif s == "}\n":
        value = -0.15
    recent = (recent + (s,))[-WINDOW:]
    return (recent, doc), value

programs.luna:
"""Guess activation from backslash pairs and angle-bracket context.

These marks lean positive near angle-bracketed text; comment openers and a few
isolated delimiters lean negative. Other tokens are predicted as zero.
"""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    previous = tokens[-2] if len(tokens) > 1 else ""

    if "\\\\" in token:
        return None, 1.16
    if token == "＞":
        return None, 0.36
    if token == ">":
        recent = "".join(tokens[max(0, len(tokens) - 8):-1])
        if "<" in recent:
            return None, 0.44
    if token in ("//", "/*", "#") and previous.isspace():
        return None, -0.44
    if token in ("*", "[", "[]", "(", ")", '"', '"""'):
        return None, -0.36
    if "\x00" in token:
        return None, -0.44
    if "\xa0" in token:
        return None, -0.20
    return None, 0.0

