    'husband': -1.38, 'husbands': -1.17, 'wife': -0.90,
    'wives': -0.76, 'boyfriend': -1.78, 'girlfriend': -0.94,
    'spouse': -0.83, 'spouses': -0.93, 'bride': -1.10,
}
