"""Detect ov-like spelling fragments, with a negative activation.

Short ov/ов endings dominate. A leading space (a new word) weakens the
response, as do longer stems. Other v/в endings respond more weakly.
Smaller branches cover ov-inflections and labial spellings in other scripts.
Only the current token is read; unmatched tokens contribute zero.
"""
READS = ()


def spelling_response(raw):
    text = raw.strip().lower()
    length = len(text)
    boundary = raw[:1].isspace()
    cyrillic = 'в' in text

    if text.endswith(('ov', 'ов')):
        if length <= 3:
            magnitude = 4.8
            if boundary:
                magnitude = 3.4 if cyrillic else 2.7
        elif length == 4:
            magnitude = 3.65 if cyrillic else 2.6
            if boundary:
                magnitude = 1.25
        else:
            magnitude = 2.65 if cyrillic else 0.85
            if boundary:
                magnitude = 1.25 if cyrillic else 0.6
        if not text.isalpha():
            magnitude *= 0.6
    elif text.endswith('ев'):
        magnitude = 1.25 if boundary else 2.9
    elif text.endswith('ev'):
        magnitude = 1.7 if length == 2 else 0.8 if length == 3 else 0.3
        if boundary:
            magnitude *= 0.55
    elif text == 'в':
