    elif not boundary and text in ('ova', 'ovo', 'ovi', 'ovy',
                                  'ovan', 'ovic', 'ovich'):
        magnitude = 1.5 if length <= 4 else 1.0
    elif 'ов' in text:
        before, after = text.rsplit('ов', 1)
        magnitude = 2.3 / max(1, len(after))
        if boundary or len(before) > 2:
            magnitude *= 0.4
