SOUND = {"audio", "sound", "sounds", "soundtrack", "auditory", "ear", "ears", "headphones"}
PEOPLE = {"speaker", "speakers", "audience", "audiences", "viewer", "viewers", "reader", "readers"}
WATCH_READ = {"watch", "watched", "watching", "watches", "read", "reading", "attend", "attended"}
CN_LISTEN = "听聽聆倾"  # Chinese characters for listening
CN_SOUND = "耳音闻"  # ear, sound, smell
CN_EAT_DRINK = "吃喝食"  # eat, drink, food
CN_WATCH = "看观"  # look at, watch


def _value(word):
    if any(c in word for c in CN_LISTEN):
        return -7.5
    if word in HEAR or "listen" in word:
        return -3.6
    if word in SOUND or any(c in word for c in CN_SOUND):
        return -1.1
    if word in PEOPLE:
        return -1.1
    if any(c in word for c in CN_EAT_DRINK):
        return -1.8
    if word in WATCH_READ or any(c in word for c in CN_WATCH):
        return -0.7
    return 0.0


