    word = prefix.token_strings[-1].strip().lower()
    v = _value(word)
    if word == "to" and len(prefix.token_strings) > 1:
        if "listen" in prefix.token_strings[-2].strip().lower():
            v = -3.5
    return carry, float(v)

programs.sol:
"""Approximate rare private-use Unicode glyph and byte-fragment responses.

Single-token decoding hides split glyphs behind replacement characters,
so inspect completed characters across byte boundaries. Give the first
64 private-use glyphs a strong negative pulse, weakening near that band's
end. Use coarse bands for other glyphs and their incomplete UTF-8 prefixes;
positive responses increase with private-use glyphs in the last 24 tokens.
Reset this history at document boundaries. Chat markers have fixed offsets.
Most ordinary, word-specific activation variation is left unexplained.
"""

READS = ()

CHAT_BOUNDARIES = {
    '<think>': 0.037,
    '</think>': 0.188,
    '<|im_start|>': -0.020,
    '<|im_end|>': -0.047,
    '<|endoftext|>': 0.027,
}


def byte_token(token):
    """Read non-ASCII byte tokens, not word-token identities."""
    if 94 <= token <= 105:
        return token + 67
    if 106 <= token <= 187:
        return token + 68
    if 222 <= token <= 254:
        return token - 94
    if token == 255:
        return 0xAD
    return None


def negative_glyph(offset):
    if offset == 0:
        return -0.17
    if offset == 1:
        return -0.82
    if offset < 16:
        return -1.50
    if offset < 32:
        return -1.30
    return -1.35 + 0.030 * (offset - 32)


def glyph_response(cp, density):
    if 0xE000 <= cp < 0xE040:
        return negative_glyph(cp - 0xE000)
    if 0xE600 <= cp < 0xE640:
        return negative_glyph(cp - 0xE600) + 0.15
    if 0xE040 <= cp < 0xE080:
        return -0.13 + 0.30 * density
    if 0xE100 <= cp < 0xE140:
        return 0.06 + 0.25 * density
    if 0xE080 <= cp < 0xF000:
        return 0.28 + 0.30 * density
    if 0xF000 <= cp < 0xF028 or 0xF600 <= cp < 0xF628:
        return -0.40
    return 0.0015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = None, ()
        start = prefix.position
    else:
        _, previous, recent, start = carry
    # Eight fully split glyphs fill a 24-token window.
    density = min(1.0, sum(recent) / 8.0)
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    byte = byte_token(token)
    value = CHAT_BOUNDARIES.get(text, 0.0015)
    completed_private = False

    if byte == 0xEE:
        value = -0.03 + 0.40 * density
    elif previous == 0xEE and byte is not None and 0x80 <= byte <= 0xBF:
        page = byte - 0x80
        if page in (0, 24):
            value = 0.08 + 0.35 * density
        elif page < 4:
            value = 0.29 + 0.07 * (page - 1) + 0.50 * density
        elif page <= 8:
            value = 0.58 + 0.50 * density
        else:
            value = 0.48 + 0.50 * density
    elif byte == 0xC2:
        value = 0.11  # Isolated lead byte for Latin-1 symbols and controls.

    if '\ufffd' in text:
        age = prefix.position - start
        # Do not complete a character using bytes from another document.
        enough_bytes = (age >= 2 or previous in (0xEE, 0xEF)
                        or (age == 1 and previous is None))
        char = prefix.text_prefixes[-1][-1:] if enough_bytes else ''
    else:
        char = text[-1:]
    if char and 0xE000 <= ord(char) <= 0xF8FF:
        completed_private = True
        value = glyph_response(ord(char), density)

    recent = (recent + (completed_private,))[-24:]
    return (doc, byte, recent, start), float(value)

