"""Predict small word-shape responses and a larger response for practical actions."""

READS = ()

ACTION_STEMS = (
    "util", "assist", "help", "support", "safeguard", "protect",
    "accomplish", "achiev", "obtain", "enable", "facilitat",
    "advantage", "benefit",
)

ENDINGS = (
    "ing", "ed", "ly", "ous", "ive", "ful", "less", "able",
    "ible", "ance", "ence", "ity", "ment", "ary", "ory", "ize",
    "ise", "ate",
)


def is_cjk(ch):
    n = ord(ch)
    return (
        0x3040 <= n <= 0x30FF
        or 0x3400 <= n <= 0x9FFF
        or 0xF900 <= n <= 0xFAFF
    )


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    if any(lower.startswith(stem) for stem in ACTION_STEMS):
        return None, 0.35
    if len(lower) >= 6 and lower.isascii() and lower.isalpha():
        if lower.endswith(ENDINGS):
            return None, 0.12
    if sum(is_cjk(ch) for ch in word) >= 2:
        return None, 0.12
    return None, 0.0

