    cur = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if cur == "many":
        value = -7.0 if prev in ("how", "too", "so", "as") else QUANTIFIER["many"]
    elif cur == "of":
        value = OF_AFTER.get(prev, 0.0)
    elif cur == "number":
        value = NUMBER_AFTER.get(prev, -0.3)
    else:
        value = QUANTIFIER.get(cur, 0.0)
