programs.haiku:
"""Layer 0, MLP down-projection, component 4149 (Qwen3-1.7B).

What this component is: a diffuse, token-specific readout with no clean word class.
Its activation is small (std 0.034) and its sign depends mostly on which token it reads.
The regularities found by hand are weak, so this program predicts only a few small
offsets by surface form:

- code-style identifiers (camelCase like `appendChild`, dotted members like `.getClass`)
  push the activation up, the strongest offset;
- capitalised words after a space (proper nouns, title-case) push it slightly down;
- lowercase words after a space push it slightly down, bare lowercase pieces slightly up;
- CJK characters push it slightly up;
- the first token of a document has no context and sits a little higher.

Everything else predicts the mean (about 0). The offsets are fit by least squares on
training rows. They explain about 0.3% of the variance: a conceptual program can't
recover much of this component. A lookup of each token's mean activation explains about
40%, but that is a table of token ids with no concept behind it, so it is not used here.
"""

import re

READS = ()

API = re.compile(r"[a-z][A-Z]|^\.[A-Za-z]|[A-Za-z]\.[a-z]")
CAP_WORD = re.compile(r" [A-Z][a-z]+")
SPACE_WORD = re.compile(r" [a-z]+")
PLAIN_WORD = re.compile(r"[a-z]+")
CJK = re.compile(r"[一-鿿]")


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    core = text.strip()
    value = -0.0003
    if API.search(text):
        value += 0.0125
    elif CAP_WORD.fullmatch(text):
        value -= 0.0037
    elif SPACE_WORD.fullmatch(text):
        value -= 0.0022
    elif PLAIN_WORD.fullmatch(text):
        value += 0.0031
    if CJK.search(text):
        value += 0.0024
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value += 0.0054
    return carry, float(value)

"""Indefinite-article detector, with context.

This component's signal is large on the English indefinite article " a" (about 0.8
on general text) and somewhat smaller on " an" (about 0.6). Capitalised " A" gets a
small level, since it is usually a title word. Everything else is near zero.

How strongly the article fires depends on the word just before it:
  - after punctuation or a line break ("the list, a ...", "Yes. A ...") it is weak;
  - after a verb or a word like "with", "had", "for", "make" it is strong;
  - otherwise it sits at the base level.
"""

import unicodedata

READS = ()

ARTICLE_LEVEL = {" a": 0.8, " an": 0.6, " A": 0.15, "a": 0.05, "A": 0.05}

STRONG_BEFORE = {
    " with", " had", " have", " has", " was", " make", " made", " like", " just",
    " not", " for", " be", " are", " on", " and", "'s", "’s", " into",
}


def is_punctuation(text):
    stripped = text.strip()
    if not stripped:
        return True  # whitespace or a line break
    return all(unicodedata.category(ch).startswith("P") for ch in stripped)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    level = ARTICLE_LEVEL.get(token, 0.0)
    if level and len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2]
        if before in STRONG_BEFORE:
            level *= 1.5
        elif is_punctuation(before):
            level *= 0.25
    return carry, level

"""Relative-clause verb detector (layer 0, MLP down_proj, component 4151).

What it does: this component reads the word that comes right after a relative
pronoun ("that", "which", "who", "whom", "whose") and says whether that pronoun is
the SUBJECT of a relative clause with its verb following it.

- "the cups that [are] ..." , "a formula that [can] ...", "people who [want] ...":
  the next word is an auxiliary, modal, or verb, so the component fires strongly
  positive (about +3 for auxiliaries/modals, about +1.5 for -s/-ed verbs, about +0.5
  for other plain words).
- "the cups that [the] ...", "the plan that [I] ...", "in which [he] ...": the pronoun
  is an object or a complementizer and the next word starts a noun phrase or subject
  pronoun, so the component is negative (about -1).
- "that's" (the contraction 's after that) counts as a verb, about +2.
- "this" and "what" followed by a verb give a weaker positive value (a quarter of the
  relative-pronoun value).
- Everywhere else the prediction is 0.

Why: the component's activation is about 73% of its total variance on positions right
after a relative pronoun, and the sign is set by whether the next word is a verb.
A word-class rule captures most of that without a lookup table of token ids.
"""

READS = ()

RELATIVE = {"that", "which", "who", "whom", "whose"}
WEAK_SUBJECT = {"this", "what"}
MODALS = {"is", "are", "was", "were", "be", "been", "being", "has", "have", "had",
          "can", "could", "will", "would", "shall", "should", "may", "might", "must",
          "do", "does", "did"}
CONTRACTED_VERB = {"'s", "’s"}
FUNCTION = {"the", "a", "an", "this", "that", "these", "those", "it", "they", "we", "i",
            "he", "she", "you", "his", "her", "their", "our", "my", "your", "its", "of",
            "in", "on", "at", "for", "to", "with", "if", "when", "there", "no", "any",
            "all", "some", "many", "such", "one", "both", "each", "every", "by", "from",
            "as", "and", "or", "but", "not", "what", "which", "who", "where", "how"}


def verb_value(word):
    """How strongly a word right after a relative pronoun looks like its verb."""
    if word in MODALS:
        return 3.0
    if word in CONTRACTED_VERB:
        return 2.0
    if word in FUNCTION:
        return -1.0
    if not word.isalpha() or len(word) < 2:
        return 0.0
    if word.endswith(("s", "ed")):
        return 1.5
    return 0.5


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    before = prefix.token_strings[t - 1].strip().lower()
    word = prefix.token_strings[t].strip().lower()
    if before in RELATIVE:
        return None, verb_value(word)
    if before in WEAK_SUBJECT:
        return None, 0.25 * verb_value(word)
    return None, 0.0

programs.luna:
"""A rough local cue for a clause continuing into a verb-like token."""
READS = ()

SUBJECTS = set("""
i you he she it we they
this that these those who which what
""".split())

AUXILIARIES = set("""
am is are was were be been being
have has had do does did
can could may might must shall should will would
""".split())

FUNCTION_WORDS = set("""
the a an any each every some no another by
""".split())


def clean(token):
    return token.strip().lower().strip('.,!?;:()[]{}\"“”')


def verb_like(word):
    return (
        word in AUXILIARIES
        or word.endswith(("s", "ed", "ing"))
        or word in ("need", "mean", "means")
    )


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    previous = ""
    if len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_document:
            previous = clean(prefix.token_strings[-2])

    if previous in SUBJECTS:
        if verb_like(word):
            return None, 0.75
        if word in FUNCTION_WORDS or word in SUBJECTS:
            return None, -0.35
    if previous in AUXILIARIES and word.endswith(("ed", "ing")):
        return None, 0.35
    return None, 0.0

