HAN_REPAIR = {
    '修': -5.3, '修正': -4.2, '修订': -3.0, '修訂': -3.0,
    '修复': -2.7, '修復': -2.7, '修理': -2.65,
    '修改': -1.9, '维修': -1.9, '維修': -1.9,
