    elif word in BETWEEN:
        value = BETWEEN[word]
    elif word == 'fix':
        value = -3.55
        if token.strip().startswith('_') or raw.isupper():
            value = -2.9
        elif word == raw and not token.startswith(' '):
            value = -3.05
    elif word == 'fixed':
        value = -2.75
        if token.strip().startswith('-'):
            value = -2.1
    elif word in {'fixing', 'fixes'}:
        value = -3.2
    elif word.startswith('fixat'):
        value = -1.55
    elif word in {'fixture', 'fixtures'}:
        value = -0.55
    elif word.startswith('repair'):
        value = -1.65
    elif word == 'correct':
        value = -0.7
    elif word in {'corrected', 'correcting', 'correction', 'corrections'}:
        value = -1.5
    elif word in EDIT_OR_AMEND:
        value = -1.0
    elif word.startswith(('adjust', 'modif', 'revis')):
        value = -0.35
    elif word.startswith('renovat'):
        value = -0.7
    elif word in {'incorrect', 'corrective'}:
