programs.haiku:
"""Layer-0 MLP unit 4152 (down_proj): a word detector with two opposite sides.

Positive on "between" (and its translations entre / zwischen / между): about +1.5.
Negative on words for fixing, repairing, correcting and editing: fix/fixed about -3,
repair and correction about -1.7, edit/amend/revise/patch about -1.1, correct about -0.7.
Everything else is predicted as 0. The rule looks only at the newest token's text.
"""
import re

READS = ()

BETWEEN = {"between": 1.6, "entre": 1.0, "zwischen": 1.1, "между": 1.5}
FIX = {"fix", "fixed", "fixes", "fixing", "修"}
REPAIR = {"repair", "repairs", "repaired", "repairing", "correction", "corrections",
          "corrected", "修复", "修正", "修理", "维修", "修改"}
EDIT = {"edit", "edited", "editing", "amend", "amended", "amendment", "revise",
        "revised", "patch"}
CORRECT = {"correct", "correcting"}


def word_of(token):
    # lowercase letters only, so " Between", "between" and "-between" all match
    return re.sub(r"[^a-zЀ-ӿ一-鿿]", "", token.lower())


def step(carry, prefix, upstream):
    w = word_of(prefix.token_strings[-1])
    if w in BETWEEN:
        return None, BETWEEN[w]
    if w in FIX:
        return None, -3.0
    if w in REPAIR:
        return None, -1.7
    if w in EDIT:
        return None, -1.1
    if w in CORRECT:
        return None, -0.7
    return None, 0.0

programs.sol:
"""Detect the beginning of a name/number introduced by a symbolic prefix.

Dollar-prefixed variable names give the strongest response; long lowercase
names are stronger than single-letter mathematical names. Percent format
codes and underscore-prefixed names respond less strongly, followed by
annotations, hash labels, references, self-members and LaTeX commands.
Token boundaries matter: fused sigils differ from separate sigil tokens.
Only the current and previous token text is used; documents reset context.
The coarse strengths leave individual-word activation differences unmodeled.
"""
READS: tuple[str, ...] = ()


def dollar_name(text, previous):
    spaced = previous.startswith(' ')
    escaped = '\\' in previous
    isolated = not previous.strip('$').strip()
    nested = '(' in previous or '[' in previous
    if text[0].isdigit():
        return 1.2 if escaped else 0.95 if spaced else 1.6
    if text[0] == '\\':
        return 1.55 if spaced else 2.05
    if not text[0].isalpha():
        return 0.0
    if len(text) == 1:
        value = 0.35 if text.isupper() else 0.7
        if not spaced:
            value += 0.65
        if escaped:
            return 2.1
        if not isolated:
            value += 0.8
    else:
        value = 2.5 if len(text) == 2 else 3.45
        if not (text.islower() or text.isupper()):
            value -= 1.2
        if escaped:
            value -= 0.9
        elif nested:
            value += 0.7
        elif previous.count('$') > 1:
            value *= 0.4
    return value


def underscore_name(text, previous):
    double = previous.endswith('__')
    if text[0].isdigit():
        return 0.65 if double else 0.07
    if '$' in previous:  # PHP's dollar-underscore variables.
        return 2.5 if previous.startswith(' ') else 2.1
    if text.islower():
        value = 0.95 if double else 0.43
    else:
        value = 0.55 if double else 0.2
    if previous.startswith(' '):
        value += 0.5 if double else 0.3
    if '.' in previous or '(' in previous:
        value += 0.95 if double else 0.4
    if '/' in previous and not double:
        value += 0.3
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    stripped = text.lstrip()
    value = 0.0
    if stripped.startswith('$'):
        body = stripped[1:]
        if body and body[0].isalpha():
            if len(body) == 1:
                value = 2.1
            else:
                value = 3.6 if body == 'this' else 5.2
        elif previous.endswith('$') and not text[0].isspace():
            value = 0.2 if '\n' in text else 1.9
        elif previous.endswith('$') and text[0].isspace():
            value = -0.2
        elif not body:
            value = 1.3 if not previous else 0.02
    elif (text.startswith('.') and text[1:2].isalpha()
          and previous.strip() in ('this', 'self')):
        value = 0.62 if previous.strip() == 'this' else 0.44
    elif text and not text[0].isspace():
        if ('$' in previous and previous.endswith('\\')
                and text[0].isalpha()):
            value = 0.33 if text.islower() else 0.08
        elif previous.endswith('$'):
            value = dollar_name(text, previous)
        elif previous.endswith('${'):
            value = 1.0 if text[0].isalnum() else 0.6
        elif text[0].isalnum():
            if previous.endswith('_'):
                value = underscore_name(text, previous)
            elif previous.endswith('%'):
                value = 0.95 if text[0].isdigit() else 1.55
            elif previous.endswith('@'):
                short_or_spaced = previous.startswith(' ') or len(text) == 1
                value = 0.35 if short_or_spaced else 0.7
            elif previous.endswith('#'):
                value = 0.42 if text[0].isdigit() else 0.5
            elif previous.endswith('&'):
                value = 0.45
            elif previous.endswith(('£', '€', '¥')) and text[0].isdigit():
                value = 0.65
            elif previous.endswith('->'):
                value = 0.5
            elif previous.endswith(('*', '!', '`', '|')):
                value = 0.2
            elif previous.endswith('{'):
                value = 0.2 if previous.startswith(' ') else 0.07
        elif text[0] in '@#%' and text[1:2].isalpha():
            value = {'%': 0.9, '@': 0.35, '#': 0.13}[text[0]]
    elif previous.endswith('$'):
        value = -0.04
    return (doc, text), float(value)

