        if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.text_prefixes[-2][-1:]
            if previous == '可':
                value = 0.45
            elif previous == '所':
                value = -0.21
            elif previous in {'乘', '除'}:
                value = 2.75
    elif chinese in YI_COMPOUNDS:
        value = YI_COMPOUNDS[chinese]
    elif chinese in {'按', '按照', '依', '通过'}:
        value = 1.35
    elif chinese in {'透过', '凭借'}:
        value = 1.05
    elif chinese in set('与由而从自已'):
        value = 0.9
    elif chinese == '因':
        value = 1.15
    elif chinese in {'因为', '由于'}:
        value = 0.7
    elif chinese in {'作为', '难以', '将', '仅'}:
        value = 0.78
    elif chinese in {'依据', '基于', '只有'}:
        value = 0.63
    elif chinese in {'用', '利用', '借', '经', '被', '已经', '根据'}:
        value = 0.55
    elif chinese in {'和', '之', '所以'}:
        value = 0.23
    elif chinese in {'就', '以及'}:
        value = 0.38
    elif chinese == '只':
        value = 0.45
    elif chinese.endswith('通过'):
        value = 1.4
    elif chinese.endswith('可以'):
        value = 0.53
    elif chinese.endswith('将'):
        value = 0.65
    elif lower in {'only', '_only', '-only'}:
        value = 1.08 if word == 'only' and raw == word else 0.9
        if word == 'Only':
            value = 1.05
    elif lower in {'through', '-through'}:
        value = 0.94 if word[0].isupper() else 0.65
    elif lower == 'throughout':
        value = 0.25
    elif lower in {'solely', 'purely'}:
        value = 0.45
    elif word in CASE_MARKERS:
        value = CASE_MARKERS[word]
    elif word.startswith('を'):
        value = 0.28
    elif word.endswith('を'):
        value = 0.35
    elif word == 'به':
        value = 0.49  # Persian 'to/by'
    elif word == 'только':
