programs.haiku:
"""Layer-0 MLP down-projection component 4154: a "means / manner / source" word detector.

The component reads the current token only. It is near zero on almost every token, and
switches on for words that introduce how, by what, or from where something is done:

- the Chinese preposition 以 ("by / with / in the manner of"): the strongest trigger by far,
  about 8.5 where it stands alone, and about 7 in formal compounds where it is still the
  means preposition (是以, 将以, 坚持以, 予以, 以其, 以此);
- other 以-words (以上, 以下, 以前, 以为 ...): weak, about 1.5;
- Chinese/Japanese/Korean prepositions and verbs of means, source, cause or use
  (通过, 按照, 依, 根据, 利用, 由, 从, 自, 将, 被, 与, 因 ...): about 0.8;
- English "through" and the "only / solely" family (only, Only, 只, 仅, solely, только),
  about 0.8;
- Japanese/Korean case particles (を, に, 을, 를, 에), about 0.8.

Everything else predicts 0. Context barely matters: a token's value is nearly the same
wherever it appears, so the program is a lookup on the token, grouped by meaning.
"""

READS = ()

# 以 standing alone: the preposition "by / with / in the manner of".
YI = "以"

# Formal compounds where 以 is still the means/manner preposition.
YI_PREPOSITION = {"是以", "将以", "坚持以", "予以", "以其", "以此", "以人民"}

# Other 以-words (以上 above, 以下 below, 以前 before, 以为 think ...): weaker.
YI_WORDS = {"以上", "以下", "以内", "以外", "以前", "以后", "以来", "以为", "以及", "以便", "以免", "以人为本", "以习近平"}

# Prepositions and verbs of means, source, cause, agency or use.
MEANS = {
    "通过", "通過", "透过", "按照", "按", "依", "根据", "根據", "利用", "凭", "靠", "借", "引",
    "经", "由", "由于", "从", "從", "自", "作为", "作為", "用", "跟", "将", "將", "与", "與",
    "而", "被", "已", "已经", "因", "因为", "因為", "从而", "可以",
}

# English "through" and "only / solely".
ENGLISH = {
    " through", "through", " Through", "Through",
    " only", "only", " Only", "Only", "-only", "_only",
    " solely", "只", "仅", "只有", " только", "только",
}

# Japanese and Korean case particles.
CASE_PARTICLES = {"を", "に", "을", "를", "에"}


def step(carry, prefix, upstream):
    """This component's activation at the last token of the prefix."""
    token = prefix.token_strings[-1]
    if token == YI:
        value = 8.5
    elif token in YI_PREPOSITION:
        value = 7.0
    elif token in YI_WORDS:
        value = 1.5
    elif token in MEANS or token in ENGLISH or token in CASE_PARTICLES:
        value = 0.8
    else:
        value = 0.0
    return carry, value

