"""Approximate a multilingual connector/particle detector.

The observed strong responses are on short relational words: English 'only' and
' through', Asian case/linking particles, and comparable prepositions. These
lexical cues get a modest positive score; other tokens default to zero.
"""
READS = ()

# Restrictive or path/means words and common grammatical particles, written as
# readable vocabulary rather than token IDs.
ENGLISH = {
    'only': 0.8, 'solely': 0.6, 'through': 0.7,
}
CJK_PARTICLES = {
    'を': 0.8, 'をする': 0.5, '与': 0.7, '與': 0.8, '从': 0.8,
    '通过': 1.0, '因': 0.8, '因为': 0.7, '以上の': 0.8,
    '我們將': 0.6, '我们将': 0.6,
}
OTHER_PARTICLES = {'을': 0.7, '를': 0.8, 'به': 0.5}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = ENGLISH.get(lower, CJK_PARTICLES.get(word, OTHER_PARTICLES.get(word, 0.0)))
