programs.sol:
"""Negative detector for version/edition wording and, more weakly, copies.

English version/edition and Chinese 版 dominate. Identifier spellings and
capitalization modulate 'version'. 'Of' inherits a response in 'version of',
'edition of', and 'copy of'. A weaker lookalike is 'vision'. Split Chinese
characters are recognized when the decoded prefix completes them. Everything
else predicts zero; one-word context resets between documents.
"""
READS = ()

VERSION_WORDS = {
    'version': -4.4,
    'versions': -3.8,
    'edition': -3.3,
    'editions': -3.0,
    'versión': -2.8,
    'versão': -2.8,
    'versões': -2.8,
}
COPY_WORDS = {'copy', 'copies', 'copied', 'copying'}
# Chinese edition, publishing, and copyright terms; 本 also counts books/copies.
PUBLISHING = {
    '版': -8.5,
    '版本': -5.7,
    '新版': -5.5,
    '手机版': -2.9,
    '正版': -2.0,
    '出版': -2.2,
    '出版社': -1.0,
    '版权': -3.1,
    '版权所有': -1.2,
    '版权归': -1.5,
    '侵权': -1.9,
    '本': -0.6,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous, strength = carry
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_./-(')
    lower = word.lower()
    value = PUBLISHING.get(word, 0.0)
    if '�' in token:
        text = prefix.text_prefixes[-1]
        if text.endswith('版'):
            lower, value = 'split edition', -9.3
        elif text.endswith('版权'):
            value = -5.3
    elif lower in VERSION_WORDS:
        value = VERSION_WORDS[lower]
        if lower in {'version', 'versions'} and not token.startswith(' '):
            value *= 0.85
            if word.isupper():
                value *= 0.7
            elif word[:1].isupper():
                value *= 0.93
            if previous in {'con', 'in', 'sub'}:
                value = -0.6  # conversion/inversion/subversion
    elif lower in COPY_WORDS:
        value = -1.0
    elif lower in {'copyright', 'copyrighted'} and not word.isupper():
        value = -1.5
    elif lower in {'vision', 'visions'}:
        value = -0.9
    elif lower == 'of':
        if previous in VERSION_WORDS:
            value = 0.7 * strength
        elif previous in COPY_WORDS:
            value = -1.3
        elif previous in {'vision', 'visions'}:
            value = -0.6
    elif lower in {'ed', 'es'} and previous in {'version', 'versions'}:
        value = -1.3
    elif word == '本' and previous == 'split edition':
        value = -4.3
    if word == '版' and previous == '排':  # 排版 means typesetting/layout
        value = -4.2
    return (doc, lower, value), float(value)

