"""Respond to version/edition and copyright language.

Strong negative responses repeatedly occur on 'version' and Chinese
edition marker '版'. Weaker responses in the harvest include vision, copying,
and copyright terms, so these get a smaller negative value. These word
cues capture only a portion of the component's contextual behavior."""
READS = ()

COPYRIGHT_WORDS = {
    "copyright", "copy", "copies", "copied", "copying",
    "版权所有", "版权", "侵权", "著作权",
