    word = prefix.token_strings[-1].strip().lower()
    if "version" in word:
        value = -5.0
    elif "版" in word:
        value = -6.0
    elif "edition" in word or word in COPYRIGHT_WORDS:
        value = -1.0
    elif word in {"vision", "visions", "division"}:
        value = -1.0
