"""A past-participle cue, with a stronger pulse in 'as + participle' phrases."""

READS = ()

IRREGULAR_PARTICIPLES = frozenset({
    "found", "given", "made", "seen", "shown", "known", "done",
    "left", "brought", "written", "taken", "built", "held", "kept",
    "set", "said", "thought", "told", "led", "paid", "read", "put",
    "got", "gone", "sent", "spent", "won", "lost", "felt", "heard",
    "met", "sold", "chosen", "driven", "grown", "drawn", "born",
    "broken", "spoken", "caught", "taught", "bought",
})


def _word(text):
    return text.strip().lower().rstrip(".,;:!?)]}\"'")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    is_participle = word.endswith("ed") or word in IRREGULAR_PARTICIPLES
    if is_participle:
        if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
            if _word(prefix.token_strings[-2]) == "as":
                return None, -1.0
        return None, -0.30
    return None, 0.0

programs.sol:
"""Detect opening delimiters, especially inline mathematics and inline code.

A space-prefixed dollar sign has a large response in mathematical context,
but a small one in prices or code. A bounded evidence score uses recent
formula closers, LaTeX, mathematical prose, prices, and programming syntax.
Closing formulas and escaped dollars reduce the score. Coefficients are
calibrated on training activations, not extracted from model weights. Other quoted-span
openers have smaller, mostly token-local responses. History resets per document.
"""
import math
import re

READS = ()
MATH_WORDS = re.compile(
 r'\b(?:algebra|equation|polynomial|theorem|lemma|proof|integral|'
 r'matrix|vector|gradient|derivative|integers?|divisor|denote|'
 r'geometry|coefficient|constant|function|calculus|formula|'
 r'linear|particle|coordinate|finite|variable|probability|eigen\w*|'
 r'graph|matrices|projection|real|satisfying|spectral)\b',re.I)
LATEX = re.compile(r'\\(?:frac|sqrt|begin|end|left|right|math\w*|'
 r'text\w*|sum|int|in|mu|alpha|beta|gamma|delta|sigma|phi|psi|'
 r'theta|lambda|omega|tau|pi|leq?|geq?|times|cdot|vec|hat|'
 r'tilde|bar|partial|lim|log|sin|cos|exp|label|ref)\b')
CODE = re.compile(r'<\?php|->|<-|=>|\b(?:public|private|protected|'
 r'function|return|echo|foreach|my)\b')
CLOSE = re.compile(r'[a-zA-Z0-9})\]]\$(?:\$)?')
VARIABLE = re.compile(r'\$[a-zA-Z_]{3}\w*|\$\{[a-zA-Z_]+')
PRICE = re.compile(r'\$\d')
MONEY_WORDS=re.compile(r'\b(?:price|cost|pay|paid|dollars?|million|'
 r'billion|budget|purchase|salary|donated|penalty|loan|revenue)\b',re.I)

def closing_formula(h):
    """Is the recent dollar followed by an expression rather than prose?"""
    if '$' not in h:
        return False
    before, tail = h.rsplit('$', 1)
    if before and before[-1] not in ' \n\t([{':
        return False
    if not tail.strip() or len(tail) > 200:
        return False
    if any('\u3040' <= c <= '\u9fff' for c in tail):
        return False
    if tail.lstrip()[:1].isdigit() and not LATEX.search(h):
        return False
    body = re.sub(r'\\[a-zA-Z]+', '', tail)
    for _ in range(3):
        body = re.sub(r'\{[^{}]*\}', '', body)
    body = re.sub(r'[a-zA-Z]+_[a-zA-Z0-9]+', '', body)
    body = re.sub(r'\b(?:sin|cos|tan|exp|log|ln|max|min|lim|AdS)\b', '', body)
    return not re.search(r'[a-zA-Z]{2,}', body)


def dollar_response(h):
    """A bounded evidence score: math raises it; money and code lower it."""
    closes = len(CLOSE.findall(h))
    latex = len(LATEX.findall(h))
    variables = len(VARIABLE.findall(h))
    prices = len(PRICE.findall(h))
    code = len(CODE.findall(h))
    words = len(MATH_WORDS.findall(h))
    def evidence(n, cap):
        return bool(n) + min(n, cap) / cap
    score = -0.33
    score += 1.03 * evidence(closes, 4) + 0.55 * evidence(latex, 8)
    score -= 0.88 * evidence(variables, 6) + 0.27 * evidence(prices, 6)
    score -= 0.64 * evidence(code, 5)
    score += 0.49 * evidence(words, 5)
    score -= 0.38 * bool(MONEY_WORDS.search(h))
    score -= 1.43 * h[-1:].isspace() + 0.87 * h.endswith('  ')
    score -= 3.31 * closing_formula(h)
    score += 1.44 * bool(re.search(
        r'\b(?:let|where|find|given|suppose|denote|that|any)\s*$', h, re.I))
    score -= 2.24 * bool(re.search(r'\d\s*$', h))
    score -= 1.26 * h.endswith('\\')
    return -0.4 + 7.7 / (1.0 + math.exp(-score))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    previous = history[-1:] or '\n'
    if s == ' $':
        value = dollar_response(history)
    elif s in (' ${', '${', ' ($'):
        value = 0.6 * dollar_response(history)
    elif s.strip() in ('$\\', '\\('):
        value = (4.65 if '(' in s else 4.18) if s.startswith(' ') else 3.1
    elif s.strip() == '$$':
        value = 3.5 if s.startswith(' ') else (2.0 if previous.isspace() else 0.0)
    elif s.strip() == '$(':
        value = 0.65 * dollar_response(history)
    elif re.fullmatch(r'\$[A-Za-z]', s):
        # An attached letter can start a variable or follow a closing dollar.
        opening = previous.isspace() and not closing_formula(history)
        code = CODE.search(history) and not LATEX.search(history)
        value = 4.2 if opening and not code else 0.05
    elif s == '$':
        if not history:
            value = 2.16
        elif previous.isspace() and not closing_formula(history):
            value = 0.7 * dollar_response(history.rstrip())
        else:
            value = 0.08
    elif s.strip() == '\\$':
        value = 0.38
    elif s == '-$':
        value = 1.1
    elif '$' in s and s.rstrip().endswith(('$', '$.', '$,', '$;')):
        value = -0.3
    elif s == ' `':
        if not history:
            value = 1.1
        elif previous.isspace():
            value = 1.4
        elif previous == '=':
            value = 0.6  # Raw string assignment, rather than prose code markup.
        elif previous in ';{}':
            value = 1.5
        else:
            value = 2.3
    elif s == ' (`':
        value = 1.52
    elif s.startswith(' `') and not s.startswith(' ``'):
        value = 1.65
    elif s.strip() == '```':
        value = 1.25
    elif s.strip() == '``':
        value = 1.0 if s.startswith(' ') else 0.63
    elif s == '`':
        value = 0.63 if not history else (1.93 if previous == '\n' else
                 1.08 if previous.isspace() else 0.08)
    elif s.strip().startswith('/**') or s.strip() == '/*':
        value = 0.65
    elif s == ' **':
        value = 0.71
    elif s == '**':
        value = 0.31
    elif s == '“':
        value = 0.82 if '\u3400' <= previous <= '\u9fff' else 0.1
    elif s == '"':
        value = 0.43 if '\u3400' <= previous <= '\u9fff' else 0.02
    elif s.strip() in ('“', '‘', '«', '「', '《', '『'):
        value = {'“': 0.35, '‘': 0.42, '«': 0.38,
                 '「': 0.8, '《': 1.14, '『': 0.7}[s.strip()]
    elif s in (' "', " '"):
        if not history or previous.isspace():
            value = -0.1
        elif previous in ':=,([{':
            value = 0.0
        else:
            line = history.rsplit('\n', 1)[-1]
            code_line = bool(CODE.search(line))
            value = (0.12 if code_line else 0.27) if s.endswith('"') else (
                0.1 if code_line else 0.39)
    elif s in ('="', '["', '=["'):
        value = 0.37
    elif s in ('<think>', '</think>'):
        value = 0.25 if s == '<think>' else 0.48
    elif s.isalpha() and re.search(r'\\begin\{[a-zA-Z]*$', history):
        value = 1.7 if s in ('align', 'aligned') else 1.2
    elif s == 'begin' and history.endswith('\\'):
        value = 0.4
    elif s == 'frac' and history.endswith('\\'):
        value = 1.0
    elif s in ('left', 'display', 'style', 'text', 'boxed') and ('\\' in history[-12:]):
        value = {'left': 0.6, 'display': 0.83, 'style': 1.7,
                 'text': 0.36, 'boxed': 0.65}[s]
    elif s == '\\[':
        value = 1.1
    elif s == '[\n':
        value = 1.65
    elif s == ' \\':
        value = 0.19
    elif s == '\\':
        value = 0.09
    else:
        value = 0.0
    return (doc, (history + s)[-1600:]), float(value)

programs.luna:
"""Conservatively recognize punctuation around math and formatted text.

A delimiter state distinguishes opening from closing math marks. Nearby price
words and code-variable spellings avoid a few dollar-sign false alarms. Other
quotation and markup cues get smaller guesses; predictions are shrunk because
these readable rules are informative but imperfect.
"""

READS = ()


def _unscaled_step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        inside_math, open_quote = False, None
    else:
        inside_math, open_quote = carry[1], carry[2]

    if "$" in token:
        mark = token.lstrip()
        # A dollar sign embedded after an expression closes math; a name
        # immediately attached to it is usually a code variable such as $this.
        if not mark.startswith("$"):
            if inside_math and not token.endswith("\\$"):
                return (doc, False, open_quote), 0.0
            return (doc, inside_math, open_quote), 0.0
        rest = mark[1:]
        if rest[:1].isalpha() or rest.startswith("_"):
            return (doc, inside_math, open_quote), 0.0
        if inside_math:
            value = 0.0
        elif token.count("$") >= 2:
            value = 2.3
        elif rest.startswith("\\"):
            value = 4.8
        elif rest.startswith("("):
            value = 4.2
        else:
            value = 5.8
        previous_words = {word.strip(" .,;:") for word in prefix.token_strings[-4:-1]}
        if previous_words.intersection(
            {"pay", "paid", "price", "cost", "fee", "salary", "budget", "spent", "worth"}
        ):
            value = 0.5
        return (doc, not inside_math, open_quote), float(value)

    if token in (r"\[", r"\("):
        return (doc, True, open_quote), 0.8
    if token in (r"\]", r"\)"):
        return (doc, False, open_quote), 0.2

    # Opening quote marks and visible markup/comment openers.
    stripped = token.lstrip()
    openers = ("“", "‘", "«", "《", "〈", "「", "『")
    closers = ("”", "’", "»", "》", "〉", "」", "』")
    if '"' in token:
        if open_quote == '"':
            return (doc, inside_math, None), 0.05
        if stripped.startswith('"'):
            return (doc, inside_math, '"'), 0.4
    if stripped.startswith(openers):
        opening = stripped[0]
        return (doc, inside_math, opening), 0.4
    if stripped.startswith(closers):
        return (doc, inside_math, None), 0.05
    if token.startswith(("/**", " **", "**", " `", "`", '="')):
        return (doc, inside_math, open_quote), 0.7

    if token in ("left", "right", "frac", "tfrac", "begin", "eq"):
        return (doc, inside_math, open_quote), 0.45 if inside_math else 0.05

    return (doc, inside_math, open_quote), 0.0


def step(carry, prefix, upstream):
    carry, value = _unscaled_step(carry, prefix, upstream)
    return carry, float(value * 0.4)

programs.haiku:
"""Layer-0 MLP down-projection feature 4159: a weak, diffuse signal.

It is near zero almost everywhere (its mean is +0.003). Three word-level tendencies shift it:
  * a noun for a group of people or an institution (government, veterans, researchers,
    companies, 政府, 公司, 法院 ...) pushes it up;
  * the word right after 'when' or 'while' pushes it up a little;
  * the word right after a contrast ('but', 'however', 'though', 'although', 'why') pushes
    it down, most of all when that word is a negation or degree adverb ('but not',
    'but still', 'but very').
Everything else gets the mean. The signal is diffuse: these rules explain under 1% of the
variance, so the program is a summary of the strongest tendencies, not a full account.
"""

READS = ()

MEAN = 0.003

ACTORS = {
    "government", "officials", "official", "officers", "authorities", "researchers",
    "researcher", "employees", "veterans", "veteran", "congress", "doctors", "doctor",
    "experts", "police", "companies", "company", "developers", "scientists", "agency",
    "military", "公司", "政府", "官方", "法院", "警方", "考生", "教育部", "行政机关",
    "行业", "大家", "人们", "专家", "研究人员", "员工", "医生", "企业",
}
CONTRAST = {"but", "however", "though", "although", "why"}
DEGREE = {"not", "very", "still", "much", "far", "so", "also", "just", "no"}
OPENERS = {"when", "while"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in ACTORS:
        return None, 0.10
    if before in CONTRAST:
        return None, -0.07 if word in DEGREE else -0.03
    if before in OPENERS:
        return None, 0.03
    return None, MEAN
